window.BANK=window.BANK||{};window.BANK["6741"]={"n":"第四章 资本主义的本质及规律","qs":[{"i":"144205","t":"单选","q":"国家数据局发布《数据要素流通指南》,明确了数据要素在不同企业间进行价值交换的规范。从商品经济产生的历史进程来看，能够使这种交换行为成为可能的社会前提条件是()","o":{"A":"A.社会分工的出现","B":"B.剩余价值的产生","C":"C.资本主义生产方式的确立","D":"D.抽象劳动的物化"},"a":"A","j":"<p>国家数据局发布《数据要素流通指南》,明确了数据要素在不同企业间进行价值交换的规范。<span style=\"color: #e03e2d;\">|</span>从商品经济产生的历史进程来看，能够使这种<span style=\"background-color: #f8cac6; color: #000000;\">交换行为成为可能</span>的<span style=\"background-color: #f8cac6; color: #000000;\">社会前提条件</span><strong>是</strong>()</p>\n<p>A.社会分工的出现&radic;</p>\n<p>B.剩余价值的产生 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，属于资本主义经济范畴</span></p>\n<p>C.资本主义生产方式的确立 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，属于资本主义经济范畴</span></p>\n<p>D.抽象劳动的物化 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，属于价值形式的深度描述</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">商品经济产生的条件有两个，其中社会分工的出现是商品经济产生和存在的前提条件。由于社会分工，不同的生产者各自生产不同的产品，产生了相互交换产品的需要。</span></p>","k":"考点54 商品经济的形成和发展","kid":"159","r":25589,"tot":42011},{"i":"144206","t":"单选","q":"“私人劳动和社会劳动的矛盾”是商品经济的基本矛盾。这一矛盾之所以被称为“基本矛盾”,是因为它决定了()","o":{"A":"A.剩余价值在不同资本家之间的分配比例","B":"B.商品生产者的命运以及商品经济产生和发展的全过程","C":"C.资本主义国家对内对外的基本经济职能","D":"D.劳动力成为商品的唯一历史必然性"},"a":"B","j":"<p>&ldquo;私人劳动和社会劳动的矛盾&rdquo;是商品经济的基本矛盾。||这一矛盾之所以被称为&ldquo;基本矛盾&rdquo;,是<strong>因<span style=\"color: #000000;\">为</span></strong><span style=\"background-color: #f8cac6; color: #000000;\">它决定了</span>()</p>\n<p>A.剩余价值在不同资本家之间的分配比例 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>B.商品生产者的命运以及商品经济产生和发展的全过程&radic;</p>\n<p>C.资本主义国家对内对外的基本经济职能 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.劳动力成为商品的唯一历史必然性 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">私人劳动和社会劳动的矛盾决定了商品生产者的命运以及商品经济产生和发展的全过程。</span></p>","k":"考点54 商品经济的形成和发展","kid":"159","r":29939,"tot":39015},{"i":"144207","t":"单选","q":"马克思主义认为，无论资本主义国家在形式上如何演变(如福利国家的出现),其作为“资产阶级委员会”的本质始终不变。这主要是指资本主义国家()","o":{"A":"A.仅仅负责处理社会公共事务","B":"B.是资产阶级进行阶级压迫的工具","C":"C.必须绝对听命于个别垄断资本家的指令","D":"D.能够通过体制改革彻底消除劳资矛盾"},"a":"B","j":"<p>马克思主义认为，无论资本主义国家在形式上如何演变(如福利国家的出现),其作为<span style=\"background-color: #f8cac6; color: #000000;\">&ldquo;资产阶级委员会&rdquo;的本质</span>始终不变。<span style=\"color: #e03e2d;\">|</span>这主要<strong>是指</strong>资本主义国家()</p>\n<p>A.<strong>仅仅</strong>负责处理社会公共事务 <span style=\"background-color: #f8cac6; color: #000000;\">包括对内对外职能，对内职能也不仅仅有社会职能</span></p>\n<p>B.是资产阶级进行阶级压迫的工具&radic;</p>\n<p>C.必须绝对<strong>听命于个别垄断资本家的指令 </strong><span style=\"background-color: #f8cac6; color: #000000;\">是整个资产阶级的总代表</span></p>\n<p>D.能够通过体制改革<strong>彻底消除</strong>劳资矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">劳资矛盾在资本主义框架下无法彻底消除</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">国家的本质是阶级统治的工具。资本主义国家无论采取何种政体或社会政策，其根本属性都是资产阶级压迫无产阶级的工具。</span></p>","k":"考点46 经济基础与上层建筑的矛盾运动及其规律（第二对社会基本矛盾）★★★★","kid":"188","r":35491,"tot":36746},{"i":"144208","t":"单选","q":"商品是用来交换、能满足人的某种需要的劳动产品，具有使用价值和价值两个属性，是使用价值和价值的矛盾统一体。决定商品交换的比例的不是商品的使用价值，而是价值。商品的价值在本质上体现出()","o":{"A":"A.生产一定使用价值的具体形式的劳动与一般人类劳动的关系","B":"B.一切劳动产品所共有的属性","C":"C.生产者之间的一定的社会关系","D":"D.私人劳动与社会劳动的关系"},"a":"C","j":"<p>商品是用来交换、能满足人的某种需要的劳动产品，具有使用价值和价值两个属性，是使用价值和价值的矛盾统一体。决定商品交换的比例的不是商品的使用价值，而是价值。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">商品的价值在本质上</span><strong>体现出</strong>()</p>\n<p>A.生产一定使用价值的具体形式的劳动与一般人类劳动的关系 <span style=\"background-color: #f8cac6; color: #000000;\">这是具体劳动和抽象劳动的关系</span></p>\n<p>B.<strong>一切</strong>劳动产品所<strong>共有的属性 </strong><span style=\"background-color: #f8cac6; color: #000000;\">这是使用价值</span></p>\n<p>C.生产者之间的一定的社会关系&radic;</p>\n<p>D.私人劳动与社会劳动的关系 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，这是商品经济的基本矛盾</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">商品的价值实体是凝结在商品中的无差别的人类劳动，在本质上体现了生产者之间的一定社会关系。</span></p>","k":"考点55 商品的二因素★★★","kid":"162","r":13656,"tot":40713},{"i":"144209","t":"单选","q":"生产商品所需要的社会必要劳动时间随着劳动生产率的变化而变化。商品的价值量()","o":{"A":"A.与生产商品所耗费的社会必要劳动时间成反比","B":"B.与生产商品所耗费的社会必要劳动时间成正比","C":"C.与生产商品所耗费的个别劳动时间成反比","D":"D.与生产商品所耗费的个别劳动时间成正比"},"a":"B","j":"<p>生产商品所需要的社会必要劳动时间随着劳动生产率的变化而变化。<span style=\"color: #e03e2d;\">|</span><strong>商品的价值量</strong>()</p>\n<p>A.与生产商品所耗费的<strong>社会必要劳动时间</strong>成<strong>反比 </strong><span style=\"background-color: #f8cac6; color: #000000;\">与劳动生产率成反比</span></p>\n<p>B.与生产商品所耗费的社会必要劳动时间成正比&radic;</p>\n<p>C.与生产商品所耗费的<strong>个别劳动时间</strong>成反比 <span style=\"background-color: #f8cac6; color: #000000;\">CD商品价值量与个别劳动时间无关</span></p>\n<p>D.与生产商品所耗费的<strong>个别劳动时间</strong>成正比</p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">商品的价值量与生产商品所耗费的社会必要劳动时间成正比。</span></p>","k":"考点57 商品价值量的决定★★★","kid":"165","r":27498,"tot":36718},{"i":"144210","t":"单选","q":"马克思说：“一切劳动，从一方面看，是人类劳动力在生理学意义上的耗费……从另一方面看，是人类劳动力在特殊的有一定目的的形式上的耗费。”这说明了生产商品的劳动是()","o":{"A":"A.具体劳动和抽象劳动的辩证统一","B":"B.私人劳动和社会劳动的辩证统一","C":"C.必要劳动和剩余劳动的辩证统一","D":"D.简单劳动和复杂劳动的辩证统一"},"a":"A","j":"<p>马克思说：&ldquo;一切劳动，从一方面看，是人类劳动力在生理学意义上的耗费&hellip;&hellip;从另一方面看，是人类劳动力在特殊的有一定目的的形式上的耗费。&rdquo;<span style=\"color: #e03e2d;\">||</span>这<strong>说明</strong>了<span style=\"background-color: #f8cac6; color: #000000;\">生产商品的劳动</span><strong>是</strong>()</p>\n<p>A.具体劳动和抽象劳动的辩证统一&radic;</p>\n<p>B.私人劳动和社会劳动的辩证统一 <span style=\"background-color: #f8cac6; color: #000000;\">任何商品生产者的劳动的两个性质，注意比较选项A的劳动二重性</span></p>\n<p>C.必要劳动和剩余劳动的辩证统一 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，这属于剩余价值理论</span></p>\n<p>D.简单劳动和复杂劳动的辩证统一 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">具体劳动和抽象劳动是商品生产者同一劳动过程的不可分割的两个方面。</span></p>","k":"考点56 生产商品的劳动二重性★★","kid":"164","r":28248,"tot":36126},{"i":"144211","t":"单选","q":"货币是在长期交换过程中形成的固定充当一般等价物的商品，是商品经济内在矛盾发展的产物，货币的本质是()","o":{"A":"A.固定充当一般等价物的商品","B":"B.凝结在商品中的无差别的一般人类劳动","C":"C.自然关系的体现","D":"D.体现一种交换关系"},"a":"A","j":"<p>货币是在长期交换过程中形成的固定充当一般等价物的商品，是商品经济内在矛盾发展的产物，<span style=\"background-color: #f8cac6; color: #000000;\">货币</span>的<strong>本质</strong>是()</p>\n<p>A.固定充当一般等价物的商品&radic;</p>\n<p>B.凝结在商品中的无差别的一般人类劳动 <span style=\"background-color: #f8cac6; color: #000000;\">这是商品价值的实体</span></p>\n<p>C.自然关系的体现 <span style=\"background-color: #f8cac6; color: #000000;\">货币的本质体现一种社会关系</span></p>\n<p>D.体现一种交换关系 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">货币的本质是固定充当一般等价物的商品。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":29019,"tot":35260},{"i":"144212","t":"单选","q":"正如马克思所指出的：“在私人劳动产品的偶然的不断变动的交换比例中，生产这些产品的社会必要劳动时间作为起调节作用的自然规律强制地为自己开辟道路，就像房屋倒在人的头上时重力定律强制地为自己开辟道路一样。因此，价值量由劳动时间决定是一个隐藏在商品相对价值的表面运动后面的秘密。”在商品经济中，价值规律的表现形式是()","o":{"A":"A.商品的价值量由生产商品的社会必要劳动时间决定","B":"B.商品交换以价值量为基础","C":"C.商品的价格围绕商品的价值自发波动","D":"D.遵循等价交换原则"},"a":"C","j":"<p>正如马克思所指出的：&ldquo;在私人劳动产品的偶然的不断变动的交换比例中，生产这些产品的社会必要劳动时间作为起调节作用的自然规律强制地为自己开辟道路，就像房屋倒在人的头上时重力定律强制地为自己开辟道路一样。因此，价值量由劳动时间决定是一个隐藏在商品相对价值的表面运动后面的秘密。&rdquo;<span style=\"color: #e03e2d;\">||</span>在商品经济中，<span style=\"background-color: #f8cac6; color: #000000;\">价值规律的表现形式</span><strong>是</strong>()</p>\n<p>A.商品的价值量由生产商品的社会必要劳动时间决定</p>\n<p>B.商品交换以价值量为基础 <span style=\"background-color: #f8cac6; color: #000000;\">AB都是价值规律的内容，而非表现形式</span></p>\n<p>C.商品的价格围绕商品的价值自发波动&radic;</p>\n<p>D.遵循等价交换原则 <span style=\"background-color: #f8cac6; color: #000000;\">都是价值规律的内容，而非表现形式</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">在商品经济中，价值规律的表现形式是商品的价格围绕商品的价值自发波动。</span></p>","k":"考点59 价值规律★★★","kid":"172","r":21049,"tot":36016},{"i":"144213","t":"单选","q":"商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，根源于()","o":{"A":"A.生产力和生产关系的矛盾","B":"B.经济基础和上层建筑的矛盾","C":"C.简单劳动和复杂劳动的矛盾","D":"D.私人劳动和社会劳动的矛盾"},"a":"D","j":"<p>商品的使用价值和价值的矛盾、生产商品的具体劳动和抽象劳动的矛盾，<span style=\"color: #e03e2d;\">||</span><strong>根源于</strong>()</p>\n<p>A.生产力和生产关系的矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">AB是社会基本矛盾运动</span></p>\n<p>B.经济基础和上层建筑的矛盾</p>\n<p>C.简单劳动和复杂劳动的矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.私人劳动和社会劳动的矛盾&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">私人劳动和社会劳动的矛盾是商品经济的基本矛盾，贯穿商品经济发展过程的始终，决定着商品经济的各种内在矛盾及其发展趋势。</span></p>","k":"考点60 以私有制为基础的商品经济的基本矛盾★★★","kid":"173","r":22871,"tot":35457},{"i":"144214","t":"单选","q":"在商品交换过程中，生产商品使用价值的具体劳动是不能直接进行量的比较的，只有将具体劳动还原为抽象劳动，也就是从具体劳动中抽象出无差别的一般人类劳动，才能进行量的比较。在私有制商品经济条件下，具体劳动能否还原为抽象劳动，在根本上取决于()","o":{"A":"A.固定充当一般等价物的商品是否形成","B":"B.私人劳动和社会劳动能否实现统一","C":"C.商品的价值和使用价值是否统一","D":"D.劳动生产力水平是否提高"},"a":"B","j":"<p>在商品交换过程中，生产商品使用价值的具体劳动是不能直接进行量的比较的，只有将具体劳动还原为抽象劳动，也就是从具体劳动中抽象出无差别的一般人类劳动，才能进行量的比较。<span style=\"color: #e03e2d;\">|</span>在私有制商品经济条件下，<span style=\"background-color: #f8cac6; color: #000000;\">具体劳动能否还原为抽象劳动</span>，<strong>在根本上取决于</strong>()</p>\n<p>A.固定充当一般等价物的商品是否形成 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>B.私人劳动和社会劳动能否实现统一&radic;</p>\n<p>C.商品的价值和使用价值是否统一</p>\n<p>D.劳动生产力水平是否提高 <span style=\"background-color: #f8cac6; color: #000000;\">CD不合题意</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">具体劳动能否还原为抽象劳动，在根本上取决于私人劳动和社会劳动能否实现统一。</span></p>","k":"考点60 以私有制为基础的商品经济的基本矛盾★★★","kid":"173","r":22439,"tot":35162},{"i":"144215","t":"单选","q":"资本主义生产的直接目的和决定性动机，就是无休止地获取尽可能多的剩余价值。剩余价值是在资本主义的生产过程中生产出来的。资本主义的生产过程具有两重性，其中主要的方面是()","o":{"A":"A.再生产资本主义生产关系的过程","B":"B.补偿劳动力的价值形成过程","C":"C.生产物质资料的劳动过程","D":"D.价值增殖过程"},"a":"D","j":"<p>资本主义生产的直接目的和决定性动机，就是无休止地获取尽可能多的剩余价值。剩余价值是在资本主义的生产过程中生产出来的。<span style=\"background-color: #f8cac6; color: #000000;\">资本主义的生产过程</span>具有两重性，其中<strong>主要的方面是</strong>()</p>\n<p>A.再生产资本主义生产关系的过程<span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">不是资本主义生产过程</span></span></p>\n<p>B.补偿劳动力的<strong>价值形成过程</strong> <span style=\"background-color: #f8cac6; color: #000000;\">只是单纯的价值形成过程，而非价值增殖过程</span></p>\n<p>C.生产物质资料的<strong>劳动过程</strong> <span style=\"background-color: #f8cac6; color: #000000;\">是资本主义的生产过程两重性中的另外一方面，不是主要方面</span></p>\n<p>D.价值增殖过程&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义的生产过程具有两重性，其中主要的方面是价值增殖过程，即剩余价值的生产过程，也是资本主义生产过程的主要方面。</span></p>","k":"考点64 资本主义生产过程★","kid":"184","r":23647,"tot":34214},{"i":"144216","t":"单选","q":"根据资本在剩余价值生产中所起的不同作用，可以将资本划分为不变资本与可变资本。不变资本是以生产资料形态存在的资本。如原材料、燃料，或者厂房、机器等。生产资料的价值通过雇佣工人的()","o":{"A":"A.具体劳动被转移到新产品中","B":"B.具体劳动被再创造出来","C":"C.抽象劳动被转移到新产品中","D":"D.抽象劳动被再生产出来"},"a":"A","j":"<p>根据资本在剩余价值生产中所起的不同作用，可以将资本划分为不变资本与可变资本。不变资本是以生产资料形态存在的资本。如原材料、燃料，或者厂房、机器等。<span style=\"background-color: #f8cac6; color: #000000;\">生产资料的价值</span>通过<strong>雇佣工人的</strong>()</p>\n<p>A.具体劳动被转移到新产品中&radic; <span style=\"background-color: #f8cac6; color: #000000;\">其转移的价值量不会大于它原有的价值量</span></p>\n<p>B.具体劳动被再<strong>创造</strong>出来</p>\n<p>C.<strong>抽象劳动</strong>被转移到新产品中 <span style=\"background-color: #f8cac6; color: #000000;\">记住一个口诀：&ldquo;人的价值要创造，物的价值要转移；抽象劳动对应人，具体劳动对应物。&rdquo;题干问的是&ldquo;生产资料&rdquo;的价值，显然对应的是&ldquo;物&rdquo;,因此动词应该对应&ldquo;转移&rdquo;,而介词应该对应&ldquo;具体劳动&rdquo;。</span></p>\n<p>D.<strong>抽象劳动</strong>被再生产出来</p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">生产资料的价值通过雇佣工人的具体劳动被转移到新产品中，其转移的价值量不会大于它原有的价值量。</span></p>","k":"考点65 资本的区分★★","kid":"185","r":21423,"tot":34294},{"i":"144217","t":"单选","q":"某商人投资200万元建设了一家新的工厂。他花了50万元租下厂房，并购买了100万元的机器和原料，其余的钱用于雇佣工人。经过一轮生产经营，该工厂获得了50万元的利润。该厂一轮生产的剩余价值率为()","o":{"A":"A.200%","B":"B.100%","C":"C.50%","D":"D.10%"},"a":"B","j":"<p>某商人投资200万元建设了一家新的工厂。他花了50万元租下厂房，并购买了100万元的机器和原料，其余的钱用于雇佣工人。经过一轮生产经营，该工厂获得了50万元的利润。<span style=\"background-color: #f8cac6; color: #000000;\">该厂一轮生产的剩余价值率</span><strong>为</strong>()</p>\n<p>A.200%</p>\n<p>B.100%&radic;</p>\n<p>C.50%</p>\n<p>D.10%</p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">雇佣工人的费用即可变资本(v)是200&mdash;50-100=50万，利润即剩余价值(m)=50,根据剩余价值率的公式为m'=m/v,得出m'=50/50=100%。</span></p>","k":"考点65 资本的区分★★","kid":"185","r":24083,"tot":31990},{"i":"144218","t":"单选","q":"剩余价值的生产是资本主义经济的绝对规律，资本家为了获得更多的剩余价值通常采取“绝对剩余价值生产”和“相对剩余价值生产”这两种方法。这两种方法的共同点在于()","o":{"A":"A.都降低了劳动力价值","B":"B.都是资本家追逐超额剩余价值的结果","C":"C.都延长了剩余劳动时间","D":"D.都缩短了必要劳动时间"},"a":"C","j":"<p>剩余价值的生产是资本主义经济的绝对规律，资本家为了获得更多的剩余价值通常采取&ldquo;绝对剩余价值生产&rdquo;和&ldquo;相对剩余价值生产&rdquo;这两种方法。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">这两种方法的共同点</span><strong>在于</strong>()</p>\n<p>A.都<strong>降低了劳动力价值 </strong><span style=\"background-color: #f8cac6; color: #000000;\">AB仅能对应相对剩余价值</span></p>\n<p>B.都是资本家<strong>追逐超额剩余价值的结果</strong></p>\n<p>C.都延长了剩余劳动时间&radic;</p>\n<p>D.都<strong>缩短了必要劳动时间</strong> <span style=\"background-color: #f8cac6; color: #000000;\">仅能对应相对剩余价值</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">绝对剩余价值绝对延长剩余劳动时间；相对剩余价值是在工作日不变的条件下通过缩短必要劳动时间从而相对延长剩余劳动时间，都延长了剩余劳动时间。</span></p>","k":"考点66 剩余价值生产的两种基本方法★","kid":"186","r":17625,"tot":33528},{"i":"144219","t":"单选","q":"超额剩余价值的实质及其来源问题，是马克思全部剩余价值学说的重要组成部分，它是建立在劳动价值论与生产商品的劳动二重性学说的基础之上的。下列关于相对剩余价值和超额剩余价值的关系表述正确的是()","o":{"A":"A.超额剩余价值和相对剩余价值都是依靠提高社会劳动生产率所获得","B":"B.相对剩余价值和超额剩余价值的生产都需要降低必要劳动时间","C":"C.超额剩余价值的出现是个别资本家追逐相对剩余价值的结果","D":"D.超额剩余价值为少数资本家获得，相对剩余价值为资本家普遍获得"},"a":"D","j":"<p>超额剩余价值的实质及其来源问题，是马克思全部剩余价值学说的重要组成部分，它是建立在劳动价值论与生产商品的劳动二重性学说的基础之上的。<span style=\"color: #e03e2d;\">|</span>下列关于<span style=\"background-color: #f8cac6; color: #000000;\">相对剩余价值和超额剩余价值的关系</span><strong>表述正确的是</strong>()</p>\n<p>A.超额剩余价值和相对剩余价值都是依靠提高<strong>社会</strong>劳动生产率所获得 <span style=\"background-color: #f8cac6; color: #000000;\">超额剩余价值是单个企业提高个别劳动生产率的结果，相对剩余价值是依靠提高社会劳动生产率的提高所获得</span></p>\n<p>B.相对剩余价值和超额剩余价值的生产都需要<strong>降低必要劳动时间</strong> <span style=\"background-color: #f8cac6; color: #000000;\">仅能对应相对剩余价值</span></p>\n<p>C.<strong>超额剩余价值</strong>的出现是个别资本家追逐相对剩余价值的<strong>结果 </strong><span style=\"background-color: #f8cac6; color: #000000;\">说反了，每个资本家都力图获得超额剩余价值，而结果是资本家都普遍获得相对剩余价值，相对剩余价值是追逐超额剩余价值的结果</span></p>\n<p>D.超额剩余价值为少数资本家获得，相对剩余价值为资本家普遍获得&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率，使其生产的商品个别价值低于社会价值。这个过程的客观后果则是整个社会各个生产部门的劳动生产率普遍提高，导致生活资料的价值下降和补偿劳动力价值的必要劳动时间缩短，剩余劳动时间延长，整个资本家阶级普遍获得相对剩余价值。</span></p>","k":"考点66 剩余价值生产的两种基本方法★","kid":"186","r":15041,"tot":33615},{"i":"144220","t":"单选","q":"资本主义生产分为简单再生产和扩大再生产。资本主义简单再生产不仅生产商品，生产剩余价值，而且还生产和再生产资本主义生产关系本身。因此，资本主义简单再生产的实质是()","o":{"A":"A.物质资料再生产和资本主义生产关系再生产的统一","B":"B.劳动过程与价值增殖过程的统一","C":"C.劳动力价值与剩余价值的统一","D":"D.具体劳动和抽象劳动的统一"},"a":"A","j":"<p>资本主义生产分为简单再生产和扩大再生产。资本主义简单再生产不仅生产商品，生产剩余价值，而且还生产和再生产资本主义生产关系本身。<span style=\"color: #e03e2d;\">|</span>因此，<span style=\"background-color: #f8cac6; color: #000000;\">资本主义简单再生产</span>的<strong>实质是</strong>()</p>\n<p>A.物质资料再生产和资本主义生产关系再生产的统一&radic;</p>\n<p>B.劳动过程与价值增殖过程的统一 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本主义生产过程</span></p>\n<p>C.劳动力价值与剩余价值的统一 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>D.具体劳动和抽象劳动的统一 <span style=\"background-color: #f8cac6; color: #000000;\">这是劳动价值论内容，任何生产商品的劳动都是具体劳动和抽象劳动的统一</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义简单再生产的实质是物质资料再生产和资本主义生产关系再生产的统一。</span></p>","k":"考点72 资本积累★★","kid":"712","r":20604,"tot":32159},{"i":"144221","t":"单选","q":"资本积累不但是社会财富占有两极分化的重要原因，而且是资本主义社会失业现象产生的根源。资本积累的源泉是()","o":{"A":"A.资本主义扩大再生产","B":"B.剩余价值","C":"C.社会财富占有两极分化","D":"D.生产社会化和生产资料资本主义私人占有之间深刻的矛盾"},"a":"B","j":"<p>资本积累不但是社会财富占有两极分化的重要原因，而且是资本主义社会失业现象产生的根源。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">资本积累</span>的<strong>源泉是</strong>()</p>\n<p>A.资本主义扩大再生产 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本主义再生产的特点，且资本积累是资本主义扩大再生产的源泉</span></p>\n<p>B.剩余价值&radic;</p>\n<p>C.社会财富占有两极分化 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本积累的影响，资本积累不但是财富占有两极分化的重要原因，而且是资本主义社会失业现象产生的根源</span></p>\n<p>D.生产社会化和生产资料资本主义私人占有之间深刻的矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本主义基本矛盾，是经济危机爆发的根本原因</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">剩余价值的资本化，就是资本积累。资本积累的源泉是剩余价值。</span></p>","k":"考点72 资本积累★★","kid":"712","r":22832,"tot":31548},{"i":"144222","t":"单选","q":"马克思指出：“我们在这里最初看到的利润，和剩余价值是一回事，不过它具有一个神秘的形式，而这个神秘的形式必然会从资本主义生产方式中产生出来。”剩余价值和利润的不同之处在于()","o":{"A":"A.剩余价值是工人剩余劳动创造的，而利润是资本家与雇佣工人一起创造的","B":"B.剩余价值是可变资本的产物，而利润被看作全部预付资本的产物","C":"C.剩余价值和利润归根结底都是由工人的劳动创造出来的","D":"D.剩余价值和利润在量上是相等的"},"a":"B","j":"<p>马克思指出：&ldquo;我们在这里最初看到的利润，和剩余价值是一回事，不过它具有一个神秘的形式，而这个神秘的形式必然会从资本主义生产方式中产生出来。&rdquo;<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">剩余价值和利润的不同之处</span><strong>在于</strong>()</p>\n<p>A.剩余价值是工人剩余劳动创造的，而<strong>利润</strong>是<strong>资本家与雇佣工人一起创造</strong>的 <span style=\"background-color: #f8cac6; color: #000000;\">利润的本质是剩余价值，仍然是工人创造的</span></p>\n<p>B.剩余价值是可变资本的产物，而利润被看作全部预付资本的产物&radic;</p>\n<p>C.剩余价值和利润<strong>归根结底</strong>都是由工人的劳动创造出来的 <span style=\"background-color: #f8cac6; color: #000000;\">正确，但不是不同之处</span></p>\n<p>D.剩余价值和利润在<strong>量上是相等的 </strong><span style=\"background-color: #f8cac6; color: #000000;\">剩余价值和利润不仅在质上是相同的，而且在量上也是相等的，这是共同点，不是不同之处</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">剩余价值和利润的不同之处在于剩余价值是可变资本的产物，而利润被看作全部预付资本的产物。</span></p>","k":"考点69 剩余价值转化为利润★","kid":"193","r":22026,"tot":31060},{"i":"144223","t":"单选","q":"在资本主义生产过程中，马克思对资本家的全部预付资本从不同的角度进行了划分，根据资本在不同阶段所发挥的不同职能，将其划分为()","o":{"A":"A.固定资本和流动资本","B":"B.商业资本和产业资本","C":"C.不变资本和可变资本","D":"D.货币资本、生产资本和商品资本"},"a":"D","j":"<p>在资本主义生产过程中，马克思对资本家的全部预付资本从不同的角度进行了划分，<span style=\"background-color: #f8cac6; color: #000000;\">根据资本在不同阶段所发挥的不同职能</span>，将其<strong>划分为</strong>()</p>\n<p>A.固定资本和流动资本 <span style=\"background-color: #f8cac6; color: #000000;\">依据资本的周转方式不同</span></p>\n<p>B.商业资本和产业资本 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>C.不变资本和可变资本 <span style=\"background-color: #f8cac6; color: #000000;\">依据剩余价值在生产中所起作用不同</span></p>\n<p>D.货币资本、生产资本和商品资本&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">马克思根据资本在不同阶段所发挥的不同职能，将其划分为货币资本、生产资本和商品资本。</span></p>","k":"考点73 资本循环","kid":"713","r":19263,"tot":31481},{"i":"144224","t":"单选","q":"资本循环是资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本在循环过程中要经历三个不同阶段，与此相联系的是资本依次执行三种不同职能。其中，在购买阶段执行的职能是()","o":{"A":"A.商品资本","B":"B.货币资本","C":"C.产业资本","D":"D.生产资本"},"a":"B","j":"<p>资本循环是资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本在循环过程中要经历三个不同阶段，与此相联系的是资本依次执行三种不同职能。其中，在<span style=\"background-color: #f8cac6; color: #000000;\">购买阶段执行的职能</span><strong>是</strong>()</p>\n<p>A.商品资本 <span style=\"background-color: #f8cac6; color: #000000;\">售卖阶段产业资本执行的职能</span></p>\n<p>B.货币资本&radic;</p>\n<p>C.产业资本 <span style=\"background-color: #f8cac6; color: #000000;\">产业资本本身不是职能</span></p>\n<p>D.生产资本 <span style=\"background-color: #f8cac6; color: #000000;\">生产阶段产业资本执行的职能</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">在购买阶段执行的职能是货币资本。</span></p>","k":"考点73 资本循环","kid":"713","r":25782,"tot":30279},{"i":"144225","t":"单选","q":"社会生产是连续不断地进行的，这种连续不断重复的生产就是再生产。社会再生产的核心问题是()","o":{"A":"A.利润转化为平均利润","B":"B.追求剩余价值","C":"C.社会总产品的实现问题","D":"D.资本有机构成的提高"},"a":"C","j":"<p>社会生产是连续不断地进行的，这种连续不断重复的生产就是再生产。<span style=\"background-color: #f8cac6; color: #000000;\">社会再生产的核心问题</span><strong>是</strong>()</p>\n<p>A.利润转化为平均利润 <span style=\"background-color: #f8cac6; color: #000000;\">剩余价值规律和竞争规律作用的必然结果，不合题意</span></p>\n<p>B.追求剩余价值 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义生产的唯一动机和直接目的就是追求剩余价值，不合题意</span></p>\n<p>C.社会总产品的实现问题&radic;</p>\n<p>D.资本有机构成的提高 <span style=\"background-color: #f8cac6; color: #000000;\">在资本主义生产过程中，资本有机构成的提高是一般趋势、规律，不合题意</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">社会再生产的核心问题是社会总产品的实现问题，即社会总产品的价值补偿和实物补偿问题。</span></p>","k":"考点75 社会再生产","kid":"715","r":12473,"tot":32344},{"i":"144226","t":"单选","q":"2008年由美国次贷危机引发了全球性的经济危机，很多西方人感叹这一次经济危机从根本上仍未超出一百多年前马克思在《资本论》中对资本主义经济危机的理论判断和精辟分析。资本主义经济危机的本质特征是()","o":{"A":"A.生产和消费两大部类比例失衡","B":"B.生产绝对过剩","C":"C.生产相对过剩","D":"D.资本主义的基本矛盾"},"a":"C","j":"<p>2008年由美国次贷危机引发了全球性的经济危机，很多西方人感叹这一次经济危机从根本上仍未超出一百多年前马克思在《资本论》中对资本主义经济危机的理论判断和精辟分析。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义经济危机的本质特征</span><strong>是</strong>()</p>\n<p>A.生产和消费两大部类比例失衡 <span style=\"background-color: #f8cac6; color: #000000;\">会导致经济危机，但不是本质特征</span></p>\n<p>B.生产绝对过剩 <span style=\"background-color: #f8cac6; color: #000000;\">基础知识错误</span></p>\n<p>C.生产相对过剩&radic;</p>\n<p>D.资本主义的基本矛盾 <span style=\"background-color: #f8cac6; color: #000000;\">这是经济危机爆发的根本原因</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">生产相对过剩是资本主义经济危机的本质特征。即相对于劳动人民有支付能力的需求来说，社会生产的商品显得过剩。</span></p>","k":"考点76 资本主义的基本矛盾与经济危机★★","kid":"716","r":18665,"tot":30932},{"i":"144227","t":"多选","q":"某种虚拟数字艺术品在市场中频繁交易。该艺术品没有实物形态，其“观赏性”存在于代码中，但其交易价格却反映了社会必要劳动时间的耗费。人们对该数字艺术品的认识表明()","o":{"A":"A.使用价值是商品的自然属性，不一定以实物形式存在","B":"B.价值是商品的本质属性，体现了商品生产者之间的社会关系","C":"C.商品的使用价值和价值在一定条件下是可以分离的","D":"D.数字艺术品是使用价值和价值的统一"},"a":"ABD","j":"<p>某种虚拟数字艺术品在市场中频繁交易。该艺术品没有实物形态，其&ldquo;观赏性&rdquo;存在于代码中，但其交易价格却反映了社会必要劳动时间的耗费。<span style=\"color: #e03e2d;\">Ⅱ</span>人们对该<span style=\"background-color: #f8cac6; color: #000000;\">数字艺术品</span>的认识<strong>表明</strong>()</p>\n<p>A.使用价值是商品的自然属性，不一定以实物形式存在&radic;</p>\n<p>B.价值是商品的本质属性，体现了商品生产者之间的社会关系&radic;</p>\n<p>C.商品的<strong>使用价值和价值在一定条件下是可以分离</strong>的 <span style=\"background-color: #f8cac6; color: #000000;\">二者作为商品的二重性，在商品体中是不可分离的统一体</span></p>\n<p>D.数字艺术品是使用价值和价值的统一&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">使用价值是商品的自然属性，价值是商品的社会属性，二者统一于商品中。数字艺术品也是商品，因此，也是两者的统一。</span></p>","k":"考点55 商品的二因素★★★","kid":"162","r":16460,"tot":30835},{"i":"144228","t":"多选","q":"随着国产AI芯片市场竞争进入白热化，一批技术领先的企业通过改进工艺大幅降低了单位产品的劳动消耗，而部分技术落后的企业则因亏损面临被兼并的局面。这一过程体现了价值规律的作用是()","o":{"A":"A.自发地调节生产资料和劳动力在社会各部门之间的分配","B":"B.刺激商品生产者改进技术，提高劳动生产率","C":"C.自发成为社会发展的根本决定力量","D":"D.导致商品生产者优胜劣汰，实现资源优化配置"},"a":"ABD","j":"<p>随着国产AI芯片市场竞争进入白热化，一批技术领先的企业通过改进工艺大幅降低了单位产品的劳动消耗，而部分技术落后的企业则因亏损面临被兼并的局面。<span style=\"color: #e03e2d;\">|</span>这一过程<span style=\"background-color: #f8cac6; color: #000000;\">体现了价值规律的作用</span><strong>是</strong>()</p>\n<p>A.自发地调节生产资料和劳动力在社会各部门之间的分配&radic;</p>\n<p>B.刺激商品生产者改进技术，提高劳动生产率&radic;</p>\n<p>C.<strong>自发成为社会发展的根本决定力量 </strong><span style=\"background-color: #f8cac6; color: #000000;\">社会发展的根本决定力量是生产力</span></p>\n<p>D.导致商品生产者优胜劣汰，实现资源优化配置&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">A、B、D分别对应价值规律的三大作用。</span></p>","k":"考点59 价值规律★★★","kid":"172","r":21929,"tot":29124},{"i":"144229","t":"多选","q":"劳动生产率指的是劳动者生产使用价值的效率。它的高低可以用单位劳动时间内生产的商品数量来测量，也可以用单位商品中所耗费的劳动时间来测量。影响劳动生产率的因素很多，主要有()","o":{"A":"A.劳动者的平均熟练程度","B":"B.科学技术的发展程度及其在生产中的应用","C":"C.生产过程的社会结合","D":"D.生产资料的规模和效能以及自然条件"},"a":"ABCD","j":"<p>劳动生产率指的是劳动者生产使用价值的效率。它的高低可以用单位劳动时间内生产的商品数量来测量，也可以用单位商品中所耗费的劳动时间来测量。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">影响劳动生产率的因素很多</span>，<strong>主要有</strong>()</p>\n<p>A.劳动者的平均熟练程度&radic;</p>\n<p>B.科学技术的发展程度及其在生产中的应用&radic;</p>\n<p>C.生产过程的社会结合&radic;</p>\n<p>D.生产资料的规模和效能以及自然条件&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">影响劳动生产率的因素主要有劳动者的平均熟练程度、科学技术的发展程度及其在生产中的应用、生产过程的社会结合、生产资料的规模和效能以及自然条件。</span></p>","k":"考点57 商品价值量的决定★★★","kid":"165","r":20825,"tot":29105},{"i":"144230","t":"多选","q":"货币是在长期交换过程中形成的固定充当一般等价物的商品，是商品经济内在矛盾发展的产物。货币具有多种职能，其中，最基本的职能有()","o":{"A":"A.价值尺度","B":"B.流通手段","C":"C.支付手段","D":"D.贮藏手段"},"a":"AB","j":"<p>货币是在长期交换过程中形成的固定充当一般等价物的商品，是商品经济内在矛盾发展的产物。<span style=\"background-color: #f8cac6; color: #000000;\">货币</span>具有多种职能，<span style=\"color: #e03e2d;\">|</span>其中，<strong>最基本的职能有</strong>()</p>\n<p>A.价值尺度&radic;</p>\n<p>B.流通手段&radic;</p>\n<p>C.支付手段 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>D.贮藏手段 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">货币最基本的职能有价值尺度、流通手段。口诀记忆为&ldquo;甲流&rdquo;。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":14522,"tot":30482},{"i":"144231","t":"多选","q":"马克思指出，价值量由劳动时间决定是一个隐藏在商品相对价值的表面运动后面的秘密。而“价格和价值量之间的量的不一致的可能性，或者价格偏离价值量的可能性，已经包含在价格形式本身中。但这并不是这种形式的缺点，相反地，却使这种形式成为这样一种生产方式的适当形式”。作为商品经济的基本规律，价值规律()","o":{"A":"A.既支配商品生产，又支配商品流通","B":"B.是资本主义社会特有的经济规律","C":"C.是一切商品经济的基本规律","D":"D.在资源配置中具有一定的盲目性和自发性"},"a":"ACD","j":"<p>马克思指出，价值量由劳动时间决定是一个隐藏在商品相对价值的表面运动后面的秘密。而&ldquo;价格和价值量之间的量的不一致的可能性，或者价格偏离价值量的可能性，已经包含在价格形式本身中。但这并不是这种形式的缺点，相反地，却使这种形式成为这样一种生产方式的适当形式&rdquo;。作为<span style=\"background-color: #f8cac6; color: #000000;\">商品经济的基本规律</span>，<strong>价值规律</strong>()</p>\n<p>A.既支配商品生产，又支配商品流通&radic;</p>\n<p>B.是资本主义社会<strong>特有</strong>的经济规律 <span style=\"background-color: #f8cac6; color: #000000;\">是一切商品经济的基本规律</span></p>\n<p>C.是<strong>一切</strong>商品经济的基本规律&radic;</p>\n<p>D.在资源配置中具有一定的盲目性和自发性&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">价值规律既支配商品生产，又支配商品流通，因为价值规律贯穿于商品经济的全部过程；是一切商品经济的基本规律；在资源配置中具有一定的盲目性和自发性，具体表现在自发地调节生产资料和劳动力在社会各生产部门之间的分配比例、自发地刺激社会生产力的发展、自发地调节社会收入的分配。</span></p>","k":"考点59 价值规律★★★","kid":"172","r":14034,"tot":30352},{"i":"144232","t":"多选","q":"价值规律贯穿于商品经济的全部过程，它既支配商品生产，又支配商品流通。价值规律在对经济活动进行自发调节时，也会造成一些消极的后果，主要表现在()","o":{"A":"A.导致收入两极分化","B":"B.导致社会资源浪费","C":"C.阻碍技术进步","D":"D.使得整个商品世界分化为两极"},"a":"ABC","j":"<p>价值规律贯穿于商品经济的全部过程，它既支配商品生产，又支配商品流通。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">价值规律</span>在对经济活动进行自发调节时，也会造成一些<span style=\"background-color: #f8cac6; color: #000000;\">消极的后果</span>，<strong>主要表现在</strong>()</p>\n<p>A.导致收入两极分化&radic;</p>\n<p>B.导致社会资源浪费&radic;</p>\n<p>C.阻碍技术进步&radic;</p>\n<p>D.使得整个商品世界分化为两极<span style=\"background-color: #f8cac6; color: #000000;\"> 这是货币出现后的影响</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">价值规律在对经济活动进行自发调节时会导致收入两极分化，导致社会资源浪费，阻碍技术进步。</span></p>","k":"考点59 价值规律★★★","kid":"172","r":10270,"tot":31420},{"i":"144233","t":"多选","q":"私人劳动和社会劳动的矛盾构成私有制基础上商品经济的基本矛盾，这一矛盾贯穿商品经济发展过程的始终，决定着商品经济的各种内在矛盾及其发展趋势。私人劳动和社会劳动的矛盾()","o":{"A":"A.是商品经济其他一切矛盾的基础","B":"B.是商品生产和商品交换的基本规律","C":"C.决定着商品生产者的命运","D":"D.决定着商品经济的本质及发展过程"},"a":"ACD","j":"<p>私人劳动和社会劳动的矛盾构成私有制基础上商品经济的基本矛盾，这一矛盾贯穿商品经济发展过程的始终，决定着商品经济的各种内在矛盾及其发展趋势。<span style=\"color: #e03e2d;\">|</span><strong>私人劳动和社会劳动的矛盾</strong>()</p>\n<p>A.是商品经济其他一切矛盾的基础&radic;</p>\n<p>B.是商品生产和商品交换的基本规律 <span style=\"background-color: #f8cac6; color: #000000;\">这是价值规律</span></p>\n<p>C.决定着商品生产者的命运&radic;</p>\n<p>D.决定着商品经济的本质及发展过程&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">私人劳动和社会劳动的矛盾是商品经济其他一切矛盾的基础，决定着商品生产者的命运，决定着商品经济的本质及发展过程。私人劳动和社会劳动是商品经济矛盾里的第一梯队K,可以对应&ldquo;决定&rdquo;&ldquo;一切&rdquo;等词。</span></p>","k":"考点60 以私有制为基础的商品经济的基本矛盾★★★","kid":"173","r":12458,"tot":30669},{"i":"144234","t":"多选","q":"在以私有制为基础的商品经济中，人与人的社会关系被物与物的关系所掩盖，从而使商品具有一种神秘的属性，似乎它具有决定商品生产者命运的神秘力量。马克思把商品世界的这种神秘性比喻为拜物教，称之为商品拜物教。私有制商品经济条件下商品世界的拜物教性质的产生，是因为()","o":{"A":"A.资本在资本主义生产过程中采取生产资料和劳动力两种形态","B":"B.劳动量只有采取价值量这一物的形式才能进行计算和比较","C":"C.人们之间一定的社会关系被物与物的关系所掩盖","D":"D.人类劳动的等同性只有采取同质的价值形式才能在交换中体现出来"},"a":"BCD","j":"<p>在以私有制为基础的商品经济中，人与人的社会关系被物与物的关系所掩盖，从而使商品具有一种神秘的属性，似乎它具有决定商品生产者命运的神秘力量。马克思把商品世界的这种神秘性比喻为拜物教，称之为商品拜物教。<span style=\"color: #e03e2d;\">Ⅱ</span>私有制商品经济条件下<span style=\"background-color: #f8cac6; color: #000000;\">商品世界的拜物教</span>性质的<span style=\"background-color: #f8cac6; color: #000000;\">产生</span>，<strong>是因为</strong>()</p>\n<p>A.资本在资本主义生产过程中采取生产资料和劳动力两种形态 <span style=\"background-color: #f8cac6; color: #000000;\">这是不变资本和可变资本的划分</span></p>\n<p>B.劳动量只有采取价值量这一物的形式才能进行计算和比较&radic;</p>\n<p>C.人们之间一定的社会关系被物与物的关系所掩盖&radic;</p>\n<p>D.人类劳动的等同性只有采取同质的价值形式才能在交换中体现出来&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">商品拜物教的产生是因为劳动量只有采取价值量这一物的形式才能进行计算和比较，人们之间一定的社会关系被物与物的关系所掩盖，人类劳动的等同性只有采取同质的价值形式才能在交换中体现出来。</span></p>","k":"考点60 以私有制为基础的商品经济的基本矛盾★★★","kid":"173","r":9264,"tot":30767},{"i":"144235","t":"多选","q":"像任何商品一样，劳动力商品也具有价值和使用价值。但是，劳动力是特殊的商品，它的价值和使用价值具有不同于普通商品的特点。“劳动力的价值，是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。”劳动力商品的价值()","o":{"A":"A.是资本主义工资的现象","B":"B.其最低界限是由生活上不可缺少的生活资料的价值决定的","C":"C.包含历史和道德的因素","D":"D.消费过程中能够创造新的价值"},"a":"BC","j":"<p>像任何商品一样，劳动力商品也具有价值和使用价值。但是，劳动力是特殊的商品，它的价值和使用价值具有不同于普通商品的特点。&ldquo;劳动力的价值，是由生产、发展、维持和延续劳动力所必需的生活必需品的价值决定的。&rdquo;<span style=\"background-color: #f8cac6; color: #000000;\">劳动力商品的价值</span>()</p>\n<p>A.是资本主义工资的现象 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义工资的本质是劳动力价值或价格</span></p>\n<p>B.其最低界限是由生活上不可缺少的生活资料的价值决定的&radic;</p>\n<p>C.包含历史和道德的因素&radic;</p>\n<p>D.消费过程中能够创造新的价值 <span style=\"background-color: #f8cac6; color: #000000;\">这是劳动力商品的使用价值的特点，不合题意</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">劳动力商品的价值其最低界限是由生活上不可缺少的生活资料的价值决定的，所以一旦劳动力价值降低到这个界限以下，劳动力就只能在萎缩的状态下维持。劳动力商品的价值包含历史和道德的因素，所以在不同的国家或在同一国家的不同历史时期，劳动者所必需的生活资料的数量和构成是有区别的。</span></p>","k":"考点63 劳动力成为商品与货币转化为资本★★★★","kid":"182","r":5982,"tot":31255},{"i":"144236","t":"多选","q":"物质资料生产过程，即劳动过程，包括三个基本要素：劳动者、劳动对象和劳动资料。劳动过程是劳动者通过有目的的活动，即运用劳动资料对劳动对象进行加工，改变自然界的物质形态，创造出满足人们某种需要的使用价值的过程。由于资本主义劳动过程的要素都被资本家所占有，由此决定了资本主义劳动过程的特点是()","o":{"A":"A.工人在资本家的监督下劳动，他们的劳动隶属于资本家","B":"B.劳动过程和价值增殖过程的统一","C":"C.劳动的成果或者产品全部归资本家所有","D":"D.物质资料再生产与资本主义生产关系再生产的统一"},"a":"AC","j":"<p>物质资料生产过程，即劳动过程，包括三个基本要素：劳动者、劳动对象和劳动资料。劳动过程是劳动者通过有目的的活动，即运用劳动资料对劳动对象进行加工，改变自然界的物质形态，创造出满足人们某种需要的使用价值的过程。<span style=\"color: #e03e2d;\">Ⅱ</span>由于<span style=\"background-color: #f8cac6; color: #000000;\">资本主义劳动过程的要素都被资本家所占有</span>，由此决定了<span style=\"background-color: #f8cac6; color: #000000;\">资本主义劳动过程</span>的<strong>特点是</strong>()</p>\n<p>A.工人在资本家的监督下劳动，他们的劳动隶属于资本家&radic;</p>\n<p>B.劳动过程和价值增殖过程的统一 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本主义生产过程</span></p>\n<p>C.劳动的成果或者产品全部归资本家所有&radic;</p>\n<p>D.物质资料再生产与资本主义生产关系再生产的统一<span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">这是资本主义再生产过程的实质</span></span></p>\n<p>【答案】AC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义劳动过程的特点是工人在资本家的监督下劳动，他们的劳动隶属于资本家；劳动的成果或者产品全部归资本家所有。</span></p>","k":"考点64 资本主义生产过程★","kid":"184","r":7728,"tot":30167},{"i":"144237","t":"多选","q":"马克思指出：”作为劳动过程和价值形成过程的统一，生产过程是商品生产过程；作为劳动过程和价值增殖过程的统一，生产过程是资本主义生产过程，是商品生产的资本主义形式。”在这个过程中，价值增殖过程是资本主义生产过程的主要方面。这一过程中()","o":{"A":"A.雇佣工人的必要劳动用于转移自身的价值","B":"B.雇佣工人的剩余劳动无偿为资本家生产剩余价值","C":"C.剩余价值是剩余劳动的凝结","D":"D.超过了劳动力价值的补偿的一定点而延长了价值的形成"},"a":"BCD","j":"<p>马克思指出：&rdquo;作为劳动过程和价值形成过程的统一，生产过程是商品生产过程；作为劳动过程和价值增殖过程的统一，生产过程是资本主义生产过程，是商品生产的资本主义形式。&rdquo;在这个过程中，<span style=\"background-color: #f8cac6; color: #000000;\">价值增殖过程是资本主义生产过程的主要方面</span>。<strong>这一过程</strong>中（）</p>\n<p>A.<strong>雇佣工人</strong>的必要劳动用于<strong>转移</strong>自身的价值 <span style=\"background-color: #f8cac6; color: #000000;\">必要劳动，用于再生产劳动力的价值，不是&ldquo;转移&rdquo;</span></p>\n<p>B.雇佣工人的<strong>剩余劳动</strong>无偿为资本家生产<strong>剩余价值</strong>&radic;</p>\n<p>C.剩余价值是剩余劳动的凝结&radic;</p>\n<p>D.超过了劳动力价值的补偿的一定点而延长了价值的形成&radic;</p>\n<p>【答案】BCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">雇佣工人的剩余劳动无偿为资本家生产剩余价值。剩余价值是剩余劳动的凝结，剩余劳动是剩余价值的唯一源泉。超过了劳动力价值的补偿的一定点而延长了价值的形成，即价值增殖过程的内涵</span></p>","k":"考点64 资本主义生产过程★","kid":"184","r":13590,"tot":27831},{"i":"144238","t":"多选","q":"根据资本在剩余价值生产过程中的作用不同，资本可以分为不变资本和可变资本。不变资本和可变资本的区别是()","o":{"A":"A.不变资本转移价值的形式不一定是一次性的，可变资本转移价值是一次性的","B":"B.工人的具体劳动转移不变资本的价值，抽象劳动转移可变资本的价值","C":"C.不变资本是以生产资料形态存在的资本，可变资本是购买劳动力的那部分资本","D":"D.不变资本的价值量不大于它原有的价值量，可变资本的价值量大于它原有的价值量"},"a":"CD","j":"<p>根据资本在剩余价值生产过程中的作用不同，资本可以分为不变资本和可变资本。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">不变资本和可变资本</span>的<strong>区别是</strong>()</p>\n<p>A.不变资本转移价值的形式不一定是一次性的，可变资本<strong>转移</strong>价值是一次性的 <span style=\"background-color: #f8cac6; color: #000000;\">可变资本不是&ldquo;转移&rdquo;价值，可变资本的做题理解同义词就是雇佣工人，不能用&ldquo;转移&rdquo;</span></p>\n<p>B.工人的具体劳动转移不变资本的价值，抽象劳动<strong>转移</strong>可变资本的价值 <span style=\"background-color: #f8cac6; color: #000000;\">转移错误</span></p>\n<p>C.不变资本是以生产资料形态存在的资本，可变资本是购买劳动力的那部分资本&radic;</p>\n<p>D.不变资本的价值量不大于它原有的价值量，可变资本的价值量大于它原有的价值量&radic;</p>\n<p>【答案】CD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">不变资本是以生产资料形态存在的资本，可变资本是购买劳动力的那部分资本。不变资本的价值量不大于它原有的价值量，可变资本的价值量大于它原有的价值量。</span></p>","k":"考点65 资本的区分★★","kid":"185","r":10712,"tot":28280},{"i":"144239","t":"多选","q":"管理科学家德鲁克指出：“生产率是一切经济价值的源泉。”没有效率就没有企业效益。提高劳动生产率是企业基础管理的出发点和落脚点，是企业管理永恒的主题。不提高劳动生产率就没法降低生产成本、不降低成本就无法提高利润。企业率先提高劳动生产率的原因是()","o":{"A":"A.使生产商品的个别劳动时间少于社会必要劳动时间","B":"B.可以提高企业生产的单位商品所包含的价值量","C":"C.资本家想要获得超额剩余价值","D":"D.想在市场竞争中占据有利位置"},"a":"ACD","j":"<p>管理科学家德鲁克指出：&ldquo;生产率是一切经济价值的源泉。&rdquo;没有效率就没有企业效益。提高劳动生产率是企业基础管理的出发点和落脚点，是企业管理永恒的主题。不提高劳动生产率就没法降低生产成本、不降低成本就无法提高利润。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">企业率先提高劳动生产率</span>的<strong>原因是</strong>()</p>\n<p>A.使生产商品的个别劳动时间少于社会必要劳动时间&radic;</p>\n<p>B.可以提高企业生产的<strong>单位商品所包含的价值量 </strong><span style=\"background-color: #f8cac6; color: #000000;\">单位商品所包含的价值量由生产商品的社会必要劳动时间决定，不是个别企业提高自己劳动生产率可以改变的</span></p>\n<p>C.资本家想要获得超额剩余价值&radic;</p>\n<p>D.想在市场竞争中占据有利位置&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">在资本主义商品生产的条件下，每个资本家总是力图不断改进技术，改善经营管理，提高劳动生产率，使其生产的商品个别价值低于社会价值，从而获得超额剩余价值。资本家想在市场竞争中占据有利位置，就会不断改进技术，提高企业的劳动生产率。</span></p>","k":"考点66 剩余价值生产的两种基本方法★","kid":"186","r":16765,"tot":26351},{"i":"144240","t":"多选","q":"在资本有机构成提高的情况下，由于可变资本的相对量的减少，资本对劳动力的需求日益相对地减少，其结果就是不可避免地造成大批工人失业，形成相对过剩人口。相对过剩人口的形式有()","o":{"A":"A.流动的过剩人口","B":"B.潜伏的过剩人口","C":"C.庞大的过剩人口","D":"D.停滞的过剩人口"},"a":"ABD","j":"<p>在资本有机构成提高的情况下，由于可变资本的相对量的减少，资本对劳动力的需求日益相对地减少，其结果就是不可避免地造成大批工人失业，形成相对过剩人口。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"color: #000000;\"><span style=\"background-color: #f8cac6;\">相对过剩人口的形式</span><strong>有</strong></span>()</p>\n<p>A.流动的过剩人口&radic;</p>\n<p>B.潜伏的过剩人口&radic;</p>\n<p>C.庞大的过剩人口 <span style=\"background-color: #f8cac6; color: #000000;\">经常性的庞大失业人口的存在，是资本主义的痼疾，但并不是相对过剩人口的形式</span></p>\n<p>D.停滞的过剩人口&radic;</p>\n<p>【答案】ABD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">相对过剩人口的形式有流动的过剩人口、潜伏的过剩人口、停滞的过剩人口，可以口诀记忆为&ldquo;浅停留&rdquo;。</span></p>","k":"考点72 资本积累★★","kid":"712","r":13873,"tot":26753},{"i":"144241","t":"多选","q":"资本循环是资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本在循环过程中要经历三个不同的阶段，与此相联系的是资本依次执行三种不同的职能。产业资本的运动必须具备的前提条件是()","o":{"A":"A.产业资本必须按照一定比例同时存在于货币资本、生产资本和商品资本三种形式中","B":"B.产业资本循环中三种职能形式的转化必须保持时间上的依次连续性","C":"C.社会生产连续不断地进行","D":"D.实现社会总产品的价值补偿和实物补偿"},"a":"AB","j":"<p>资本循环是资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本在循环过程中要经历三个不同的阶段，与此相联系的是资本依次执行三种不同的职能。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">产业资本的运动</span>必须<strong>具备的前提条件是</strong>()</p>\n<p>A.产业资本必须按照一定比例同时存在于货币资本、生产资本和商品资本三种形式中&radic;</p>\n<p>B.产业资本循环中三种职能形式的转化必须保持时间上的依次连续性&radic;</p>\n<p>C.社会生产连续不断地进行 <span style=\"background-color: #f8cac6; color: #000000;\">这是社会总资本的运动，即社会再生产，与题意无关</span></p>\n<p>D.实现社会总产品的价值补偿和实物补偿 <span style=\"background-color: #f8cac6; color: #000000;\">这是社会再生产的核心问题</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">产业资本必须按照一定比例同时存在于货币资本、生产资本和商品资本三种形式中，即三种职能形式必须在空间上并存。产业资本循环中三种职能形式的转化必须保持时间上的依次连续性，即三种职能形式必须在时间上继起。</span></p>","k":"考点73 资本循环","kid":"713","r":7700,"tot":28118},{"i":"144242","t":"多选","q":"资本是在运动中增殖的，资本周而复始、不断反复循环，叫作资本的周转。如果每次资本周转带来的剩余价值一定，则资本周转越快，在一定时期内带来的剩余价值就越多。影响资本周转快慢的关键因素有()","o":{"A":"A.生产资本中固定资本和流动资本的构成","B":"B.可变资本和不变资本的构成","C":"C.资本有机构成","D":"D.资本周转时间"},"a":"AD","j":"<p>资本是在运动中增殖的，资本周而复始、不断反复循环，叫作资本的周转。如果每次资本周转带来的剩余价值一定，则资本周转越快，在一定时期内带来的剩余价值就越多。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">影响资本周转快慢的关键因素</span><strong>有</strong>()</p>\n<p>A.生产资本中固定资本和流动资本的构成&radic;</p>\n<p>B.可变资本和不变资本的构成 <span style=\"background-color: #f8cac6; color: #000000;\">无关</span></p>\n<p>C.资本有机构成 <span style=\"background-color: #f8cac6; color: #000000;\">无关</span></p>\n<p>D.资本周转时间&radic;</p>\n<p>【答案】AD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">影响资本周转快慢的关键因素有生产资本中固定资本和流动资本的构成、资本周转时间。</span></p>","k":"考点74 资本周转","kid":"714","r":11584,"tot":26992},{"i":"144243","t":"多选","q":"资本家购买工人的劳动力是以货币工资形式支付的，工人为资本家劳动，资本家付给工人工资，工资表现为“劳动的价格”或工人全部劳动的报酬，但它()","o":{"A":"A.遮蔽了资本主义工资的本质是剩余价值的一部分","B":"B.模糊了工人必要劳动和剩余劳动的界限","C":"C.掩盖了资本主义的剥削关系","D":"D.否认了工人具体劳动转移可变资本的价值"},"a":"BC","j":"<p>资本家购买工人的劳动力是以货币工资形式支付的，工人为资本家劳动，资本家付给工人工资，<span style=\"background-color: #f8cac6; color: #000000;\">工资表现为&ldquo;劳动的价格&rdquo;或工人全部劳动的报酬</span>，但<strong>它</strong>()</p>\n<p>A.遮蔽了资本主义<strong>工资的本质</strong>是剩余价值的一部分 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义工资的本质是劳动力的价值或价格，而非剩余价值的一部分</span></p>\n<p>B.模糊了工人必要劳动和剩余劳动的界限&radic;</p>\n<p>C.掩盖了资本主义的剥削关系&radic;</p>\n<p>D.否认了工人具体劳动<strong>转移可变资本</strong>的价值 <span style=\"background-color: #f8cac6; color: #000000;\">转移错误，可变资本的价值在生产过程中不是被转移到新产品中去，而是由工人的劳动再生产出来</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">工资模糊了工人必要劳动和剩余劳动的界限，掩盖了资本主义的剥削关系。</span></p>","k":"考点68 资本主义工资★","kid":"192","r":9624,"tot":27531},{"i":"144244","t":"多选","q":"20世纪以来，资本主义经济危机不断，并呈现出周期性的趋势。当前，欧美国家的金融问题尤其明显，美元有美债危机，欧元有欧债危机。国际清算银行在一份报告中警告称，危险的新资产泡沫正在形成，这可能导致另一场金融危机爆发。资本主义经济危机()","o":{"A":"A.形式上的可能性是由货币作为流通手段和支付手段引起的","B":"B.爆发的根本原因是资本主义基本矛盾","C":"C.实际上是资本主义条件下以强制的方式解决社会再生产的实现问题的途径","D":"D.使得社会资本再生产也呈现出周期性特点"},"a":"ABCD","j":"<p>20世纪以来，资本主义经济危机不断，并呈现出周期性的趋势。当前，欧美国家的金融问题尤其明显，美元有美债危机，欧元有欧债危机。国际清算银行在一份报告中警告称，危险的新资产泡沫正在形成，这可能导致另一场金融危机爆发。<span style=\"color: #e03e2d;\">|</span><strong>资本主义经济危机</strong>()</p>\n<p>A.<strong>形式上的可能性</strong>是由货币作为流通手段和支付手段引起的&radic;</p>\n<p>B.爆发的<strong>根本原因</strong>是资本主义基本矛盾&radic;</p>\n<p>C.<strong>实际上</strong>是资本主义条件下以强制的方式解决社会再生产的实现问题的途径&radic;</p>\n<p>D.使得社会资本再生产也呈现出<strong>周期性特点</strong>&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义经济危机形式上的可能性是由货币作为流通手段和支付手段引起的，爆发的根本原因是资本主义基本矛盾，实际上是资本主义条件下以强制的方式解决社会再生产的实现问题的途径，使得社会资本再生产也呈现出周期性特点。</span></p>","k":"考点76 资本主义的基本矛盾与经济危机★★","kid":"716","r":9872,"tot":27238},{"i":"144245","t":"单选","q":"某产业资本家获得了一笔产业利润，而其支付给银行的利息却呈现上涨趋势。从性质上看，银行资本家获得的“利息”是()","o":{"A":"A.产业资本家所雇佣工人创造的剩余价值的一部分","B":"B.银行资本家创造的新价值","C":"C.借贷资本家通过“钱生钱”自发产生的增值额","D":"D.借贷资本家对产业利润的完全替代"},"a":"A","j":"<p>某产业资本家获得了一笔产业利润，而其支付给银行的利息却呈现上涨趋势。<span style=\"color: #e03e2d;\">|</span>从性质上看，银行资本家获得的&ldquo;利息&rdquo;<strong>是</strong>()</p>\n<p>A.产业资本家所雇佣工人创造的剩余价值的一部分&radic;</p>\n<p>B.银行<strong>资本家创造</strong>的新价值 <span style=\"background-color: #f8cac6; color: #000000;\">资本家并不会创造剩余价值</span></p>\n<p>C.借贷资本家通过&ldquo;钱生钱&rdquo;<strong>自发</strong>产生的增值额 <span style=\"background-color: #f8cac6; color: #000000;\">资本不会自发增值</span></p>\n<p>D.借贷资本家对产业利润的<strong>完全替代 </strong><span style=\"background-color: #f8cac6; color: #000000;\">绝对表述K错误</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">利息的本质是剩余价值的一种转化形式。产业资本家将其获得的剩余价值(利润)的一部分支付给借贷资本家作为使用资本的报酬。因此，利息是剩余价值的一部分。</span></p>","k":"","kid":"","r":16912,"tot":25821},{"i":"144246","t":"单选","q":"在我们的日常生活中，生产者在生产商品时耗费了脑力劳动和体力劳动，这共同构成了抽象劳动，而具体劳动和抽象劳动共同构成了劳动的二重性。不同的具体劳动能创造出不同的()","o":{"A":"A.商品的价值","B":"B.商品的交换价值","C":"C.商品的使用价值","D":"D.商品的价值形式"},"a":"C","j":"<p>在我们的日常生活中，生产者在生产商品时耗费了脑力劳动和体力劳动，这共同构成了抽象劳动，而具体劳动和抽象劳动共同构成了劳动的二重性。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">不同的具体劳动</span><strong>能创造出不同的</strong>()</p>\n<p>A.商品的<strong>价值</strong> <span style=\"background-color: #f8cac6; color: #000000;\">对应K:抽象劳动</span></p>\n<p>B.商品的<strong>交换价值 </strong><span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>C.商品的使用价值&radic;</p>\n<p>D.商品的<strong>价值形式 </strong><span style=\"background-color: #f8cac6; color: #000000;\">货币是商品的价值形式的表现，其本质是一般等价物</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">对应K:具体劳动&mdash;使用价值一自然属性&mdash;具体形式、有差别、特殊</span></p>","k":"考点56 生产商品的劳动二重性★★","kid":"164","r":18420,"tot":25537},{"i":"144247","t":"单选","q":"马克思在《资本论》中指出：“不管生产力发生了什么变化，同一劳动在同样的时间内提供的价值量总是相同的。但它在同样的时间内提供的使用价值量是不同的：生产力提高时就多些，生产力降低时就少些。”这段话表明，生产力的变化()","o":{"A":"A.不影响同一劳动在同样的时间内生产的商品数量","B":"B.不改变同一劳动在同样的时间内的生产效率","C":"C.影响同一劳动在同样的时间内生产的单个商品价值量","D":"D.改变同一劳动在同样的时间内提供的价值总量"},"a":"C","j":"<p>马克思在《资本论》中指出：&ldquo;不管生产力发生了什么变化，同一劳动在同样的时间内提供的价值量总是相同的。但它在同样的时间内提供的使用价值量是不同的：生产力提高时就多些，生产力降低时就少些。&rdquo;<span style=\"color: #e03e2d;\">||</span><strong>这段话表明</strong>，<span style=\"color: #000000;\"><span style=\"background-color: #f8cac6;\">生产力的变化</span>(</span>)</p>\n<p>A.<strong>不影响</strong>同一劳动在同样的时间内生产的商品数量 <span style=\"background-color: #f8cac6; color: #000000;\">生产力提高，同一劳动在同一时间内生产的商品数量提高</span></p>\n<p>B.<strong>不改变</strong>同一劳动在同样的时间内的生产效率 <span style=\"background-color: #f8cac6; color: #000000;\">生产力提高，同一劳动在同一时间内的生产效率提高</span></p>\n<p>C.影响同一劳动在同样的时间内生产的单个商品价值量&radic;</p>\n<p>D.<strong>改变</strong>同一劳动在同样的时间内提供的<strong>价值总量 </strong><span style=\"background-color: #f8cac6; color: #000000;\">生产力提高，同一劳动在同一时间(单位时间)内提供的价值量不变</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">生产力提高，同一劳动在同一时间(单位时间)内生产的单个商品价值量降低。</span></p>","k":"考点57 商品价值量的决定★★★","kid":"165","r":17134,"tot":25556},{"i":"144248","t":"单选","q":"《资本论》中有这样的表述“对上衣来说，无论是裁缝自己穿还是他的顾客穿，都是一样的”,这主要是因为无论谁穿()","o":{"A":"A.上衣都起到使用价值的作用","B":"B.上衣都起到着价值的作用","C":"C.上衣都是抽象劳动的结果","D":"D.上衣都是社会劳动的结果"},"a":"A","j":"<p>《资本论》中有这样的表述&ldquo;对上衣来说，<span style=\"background-color: #f8cac6; color: #000000;\">无论</span>是裁缝自己穿还是他的顾客<span style=\"background-color: #f8cac6; color: #000000;\">穿，都是一样</span>的&rdquo;,<span style=\"background-color: #f8cac6; color: #000000;\">这主要是因为</span>无论谁穿()</p>\n<p>A.上衣都起到使用价值的作用&radic;</p>\n<p>B.上衣都起到着<strong>价值</strong>的作用 <span style=\"background-color: #f8cac6; color: #000000;\">与题意无关</span></p>\n<p>C.上衣都是<strong>抽象劳动</strong>的结果 <span style=\"background-color: #f8cac6; color: #000000;\">既然不是强调价值，价值的对应词抽象劳动不能选</span></p>\n<p>D.上衣都是<strong>社会劳动</strong>的结果 <span style=\"background-color: #f8cac6; color: #000000;\">每个商品生产者的劳动都是社会总劳动的一部分，是具有社会性质的社会劳动，交换是解决私人劳动和社会劳动之间矛盾的唯一途径。材料与交换无关</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">无论谁穿都一样强调上衣的有用性，即使用价值。</span></p>","k":"考点55 商品的二因素★★★","kid":"162","r":22312,"tot":24507},{"i":"144249","t":"单选","q":"在相同的劳动时间里，复杂劳动创造的价值大于简单劳动创造的价值。在以私有制为基础的商品经济条件下，复杂劳动转化为简单劳动是()","o":{"A":"A.市场管理部门事先规定的","B":"B.商品生产者计算的","C":"C.商品生产者协商的","D":"D.商品交换市场机制自发实现的"},"a":"D","j":"<p>在相同的劳动时间里，复杂劳动创造的价值大于简单劳动创造的价值。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">在以私有制为基础的商品经济条件下</span>，<strong>复杂劳动转化为简单劳动是</strong>()</p>\n<p>A.市场管理部门<strong>事先规定</strong>的 <span style=\"background-color: #f8cac6; color: #000000;\">错误</span></p>\n<p>B.商品生产者<strong>计算的</strong><span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">错误</span></span></p>\n<p>C.商品生产者<strong>协商的</strong> <span style=\"background-color: #f8cac6; color: #000000;\">错误</span></p>\n<p>D.商品交换市场机制自发实现的&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">复杂劳动等于自乘的或多倍的简单劳动。</span></p>","k":"考点57 商品价值量的决定★★★","kid":"165","r":20950,"tot":24596},{"i":"144250","t":"单选","q":"商品的价值量同简单劳动和复杂劳动有密切的关系。在相同的劳动时间里，复杂劳动所创造的价值比简单劳动所创造的价值大，是因为()","o":{"A":"A.复杂劳动是每个人都能从事的劳动","B":"B.简单劳动是有一定技术专长的劳动","C":"C.少量的复杂劳动等于多量的简单劳动","D":"D.复杂劳动决定商品的价值量大小"},"a":"C","j":"<p>商品的价值量同简单劳动和复杂劳动有密切的关系。在相同的劳动时间里，<span style=\"background-color: #f8cac6; color: #000000;\">复杂劳动所创造的价值比简单劳动所创造的价值大</span>，<strong>是因为</strong>()</p>\n<p>A.复杂劳动是<strong>每个人都能从事的</strong>劳动 <span style=\"background-color: #f8cac6; color: #000000;\">复杂劳动是指需要经过专门训练和培养，具有一定文化知识和技术专长的劳动者所从事的劳动，不是每个人都能从事的</span></p>\n<p>B.<strong>简单劳动</strong>是有<strong>一定技术专长</strong>的劳动 <span style=\"background-color: #f8cac6; color: #000000;\">这是复杂劳动</span></p>\n<p>C.少量的复杂劳动等于多量的简单劳动&radic;</p>\n<p>D.复杂劳动<strong>决定</strong>商品的价值量大小 <span style=\"background-color: #f8cac6; color: #000000;\">社会必要劳动时间决定商品价值量</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">复杂劳动等于自乘的或多倍的简单劳动。</span></p>","k":"考点57 商品价值量的决定★★★","kid":"165","r":18803,"tot":24974},{"i":"144251","t":"单选","q":"移动支付是指利用手机等移动终端对商品或服务的交易进行结算的一种方式。随着移动支付手段的兴起，越来越多的消费者开始通过移动支付方式完成交易。在移动支付中()","o":{"A":"A.货币已不再是商品交换的媒介","B":"B.货币履行的是流通手段职能","C":"C.货币执行的是支付手段职能","D":"D.只需要观念中、想象中的货币"},"a":"B","j":"<p>移动支付是指利用手机等移动终端对商品或服务的交易进行结算的一种方式。随着移动支付手段的兴起，越来越多的消费者开始通过移动支付方式完成交易。<span style=\"color: #e03e2d;\">||</span>在<span style=\"background-color: #f8cac6; color: #000000;\">移动支付</span>中()</p>\n<p>A.货币<strong>已不再是</strong>商品交换的媒介 <span style=\"background-color: #f8cac6; color: #000000;\">基础知识错误</span></p>\n<p>B.货币履行的是流通手段职能&radic;</p>\n<p>C.货币执行的是<strong>支付手段</strong>职能 <span style=\"background-color: #f8cac6; color: #000000;\">未强调赊账、欠款等提前或延期交易</span></p>\n<p>D.只需要<strong>观念中</strong>、想象中的货币 <span style=\"background-color: #f8cac6; color: #000000;\">移动支付需要现实的货币</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">移动支付也是交易，履行货币流通手段职能。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":13839,"tot":25988},{"i":"144252","t":"单选","q":"马克思在《资本论》中指出：“一个商品占有者出售他现有的商品，而另一个商品占有者却只是作为货币的代表或作为未来货币的代表来购买这种商品。卖者成为债权人，买者成为债务人。由于商品的形态变化或商品的价值形式的发展在这里起了变化，货币也就取得了另一种职能。”这里所论述的货币“另一种职能”指的是()","o":{"A":"A.价值尺度","B":"B.流通手段","C":"C.贮藏手段","D":"D.支付手段"},"a":"D","j":"<p>马克思在《资本论》中指出：&ldquo;一个商品占有者出售他现有的商品，而另一个商品占有者却只是作为货币的代表或作为未来货币的代表来购买这种商品。<span style=\"background-color: #f8cac6; color: #000000;\">卖者成为债权人，买者成为债务人</span>。由于商品的形态变化或商品的价值形式的发展在这里起了变化，<span style=\"background-color: #f8cac6; color: #000000;\">货币也就取得了另一种职能</span>。&rdquo;<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">这里所论述的货币&ldquo;另一种职能&rdquo;</span><strong>指的是</strong>()</p>\n<p>A.价值尺度 <span style=\"background-color: #f8cac6; color: #000000;\">对应K:标价，不合题意</span></p>\n<p>B.流通手段 <span style=\"background-color: #f8cac6; color: #000000;\">对应K:即时现场交易，不合题意</span></p>\n<p>C.贮藏手段 <span style=\"background-color: #f8cac6; color: #000000;\">对应K:贮藏，必须是足值的，不合题意</span></p>\n<p>D.支付手段&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">提前或延期交易，如欠债赊账、工资等，符合材料中&ldquo;债权人&rdquo;&ldquo;债务人&rdquo;的意思。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":16641,"tot":25336},{"i":"144253","t":"单选","q":"马克思把商品转换成货币称为“商品的惊险的跳跃”,这个跳跃如果不成功，摔坏的不是商品，但一定是商品的占有者。这是因为只有商品变为货币()","o":{"A":"A.货币才能转化为资本","B":"B.价值才能转化为使用价值","C":"C.抽象劳动才能转化为具体劳动","D":"D.私人劳动才能转化为社会劳动"},"a":"D","j":"<p>马克思把商品转换成货币称为&ldquo;商品的惊险的跳跃&rdquo;,这个跳跃如果不成功，摔坏的不是商品，但一定是商品的占有者。<span style=\"color: #e03e2d;\">|</span><strong>这是因为</strong><span style=\"color: #000000;\"><span style=\"background-color: #f8cac6;\">只有商品变为货币</span>(</span>)</p>\n<p>A.货币才能转化为<strong>资本 </strong><span style=\"background-color: #f8cac6;\">这<span style=\"color: #000000;\">是剩余价值理论的内容，劳动力成为商品是货币转化为资本的前提</span></span></p>\n<p>B.价值才能<strong>转化为</strong>使用价值 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述，商品转换成为货币，是商品占有者&ldquo;出让&rdquo;商品的使用价值，从而&ldquo;获得&ldquo;商品的价值</span></p>\n<p>C.抽象劳动才能<strong>转化</strong>为具体劳动 <span style=\"background-color: #f8cac6; color: #000000;\">这是同一劳动的两重性质，不是&ldquo;转化&rdquo;而是&ldquo;还原&rdquo;。生产商品使用价值的具体劳动是不能直接进行量的比较的，只有将具体劳动还原为抽象劳动，才能进行量的比较</span></p>\n<p>D.私人劳动才能转化为社会劳动&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">私人劳动要转化为社会劳动，就必须用自己的产品去同别人的产品交换。交换是解决私人劳动和社会劳动之间矛盾的唯一途径。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":12493,"tot":26216},{"i":"144254","t":"单选","q":"马克思主义政治经济学的理论十分丰富，其中“理解政治经济学的枢纽”的理论是()","o":{"A":"A.剩余价值理论","B":"B.价值规律理论","C":"C.劳动二重性理论","D":"D.商品二因素理论"},"a":"C","j":"<p>马克思主义政治经济学的理论十分丰富，<span style=\"color: #e03e2d;\">||</span>其中<span style=\"background-color: #f8cac6; color: #000000;\">&ldquo;理解政治经济学的枢纽&rdquo;的理论</span><strong>是</strong>()</p>\n<p>A.剩余价值理论<span style=\"color: #000000;\"> <span style=\"background-color: #f8cac6;\">不合题意，剩余价值理论是马克思经济学说的核心内容和基石</span></span></p>\n<p>B.价值规律理论 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意，价值规律是商品经济的基本经济规律</span></p>\n<p>C.劳动二重性理论&radic;</p>\n<p>D.商品二因素理论 <span style=\"background-color: #f8cac6; color: #000000;\">不合题意</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">劳动二重性理论为剩余价值论的创立奠定了基础，是&ldquo;理解政治经济学的枢纽&rdquo;。</span></p>","k":"考点56 生产商品的劳动二重性★★","kid":"164","r":13495,"tot":25699},{"i":"144255","t":"单选","q":"劳动力成为商品是货币转化为资本的前提条件，这是因为()","o":{"A":"A.资本家购买的是劳动力的价值","B":"B.劳动力商品具有价值和使用价值","C":"C.货币所有者购买的劳动力能够带来剩余价值","D":"D.劳动力自身的价值能够在消费过程中转移到新的商品中"},"a":"C","j":"<p>劳动力成为商品是货币转化为资本的前提条件，<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">这是因为</span>()</p>\n<p>A.资本家<strong>购买的是</strong>劳动力的价值 <span style=\"background-color: #f8cac6; color: #000000;\">购买的是劳动力商品，因为劳动力商品具有一般商品没有的特点</span></p>\n<p>B.劳动力商品具有价值和使用价值 <span style=\"background-color: #f8cac6; color: #000000;\">正确，但不合题意</span></p>\n<p>C.货币所有者购买的劳动力能够带来剩余价值&radic;</p>\n<p>D.<strong>劳动力自身的价值</strong>能够在消费过程中<strong>转移到</strong>新的商品中 <span style=\"background-color: #f8cac6; color: #000000;\">劳动力自身的价值是不会转移到新的商品中去的，是通过雇佣劳动者的必要劳动再生产出来的</span></p>\n<p>【答案】C<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">劳动力商品在使用价值上有一个很大的特点，就是它的使用价值是价值的源泉，它在消费过程中能够创造新价值，而且这个新的价值比劳动力本身的价值更大，货币所有者购买到这种特殊商品，能够获得剩余价值.货币也就转化为资本。</span></p>","k":"考点63 劳动力成为商品与货币转化为资本★★★★","kid":"182","r":15077,"tot":25240},{"i":"144256","t":"单选","q":"像任何商品一样，劳动力商品也具有价值和使用价值。但是，劳动力是特殊的商品，它的价值和使用价值具有不同于普通商品的特点。与普通商品相比，劳动力商品的特殊之处在于()","o":{"A":"A.它的使用价值是价值的源泉，能够在消费过程中创造新的更大的价值","B":"B.它是使用价值和价值的矛盾统一体，任何所有者不能同时占有","C":"C.它是遵循价值规律的自由、平等的雇佣关系","D":"D.它的价值能够在消费中转移到新产品中去"},"a":"A","j":"<p>像任何商品一样，劳动力商品也具有价值和使用价值。但是，劳动力是特殊的商品，它的价值和使用价值具有不同于普通商品的特点。<span style=\"color: #e03e2d;\">|</span>与普通商品相比，<span style=\"background-color: #f8cac6; color: #000000;\">劳动力商品的特殊之处</span><strong>在于</strong>()</p>\n<p>A.它的使用价值是价值的源泉，能够在消费过程中创造新的更大的价值&radic;</p>\n<p>B.它是使用价值和价值的矛盾统一体，任何所有者不能同时占有 <span style=\"background-color: #f8cac6; color: #000000;\">一切商品都有二因素，不是特殊之处</span></p>\n<p>C.它是遵循价值规律的<strong>自由、平等</strong>的雇佣关系 <span style=\"background-color: #f8cac6;\"><span style=\"color: #000000;\">雇佣关系不是自由、平等的，是剥削的</span></span></p>\n<p>D.它的价值能够在消费中<strong>转移到</strong>新产品中去 <span style=\"background-color: #f8cac6; color: #000000;\">劳动力商品在消费过程中能够创造新的价值，但并不会转移到新产品中去</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">劳动力商品的特殊之处在于它的使用价值是价值的源泉，能够在消费过程中创造新的更大的价值，即能够带来剩余价值。</span></p>","k":"考点63 劳动力成为商品与货币转化为资本★★★★","kid":"182","r":19647,"tot":24319},{"i":"144257","t":"单选","q":"第二次世界大战以后，资本主义国家经历了第三次科技革命，机器大工业发展到自动化阶段，智能化工厂创造出了较高的生产效率，显露出巨大的竞争力，企业在“机器换人”中取得了一定的经济效益。这意味着率先使用机器人的个别企业()","o":{"A":"A.资本技术构成的提高","B":"B.剩余价值来源的改变","C":"C.所生产商品价值的提高","D":"D.获得更多的社会平均利润"},"a":"A","j":"<p>第二次世界大战以后，资本主义国家经历了第三次科技革命，机器大工业发展到自动化阶段，智能化工厂创造出了较高的生产效率，显露出巨大的竞争力，<span style=\"background-color: #f8cac6; color: #000000;\">企业在&ldquo;机器换人&rdquo;</span>中取得了一定的经济效益。<span style=\"color: #e03e2d;\">||</span>这<strong>意味着</strong><span style=\"background-color: #f8cac6; color: #000000;\">率先使用机器人的个别企业</span>()</p>\n<p>A.资本技术构成的提高&radic;</p>\n<p>B.剩余价值来源的<strong>改变 </strong><span style=\"background-color: #f8cac6; color: #000000;\">剩余价值的唯一源泉是剩余劳动</span></p>\n<p>C.所生产商品价值的提高 <span style=\"background-color: #f8cac6;\"><span style=\"color: #000000;\">商品价值是由生产商品的社会必要劳动时间决定的，不是由个别企业影响的</span></span></p>\n<p>D.获得更多的社会平均利润 <span style=\"background-color: #f8cac6; color: #000000;\">个别企业改进技术可以获得更多的超额剩余价值，但不会获得更多的社会平均利润</span></p>\n<p>【答案】A<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本技术构成的提高对应的是技术水平的提高，符合题意。</span></p>","k":"考点72 资本积累★★","kid":"712","r":16587,"tot":24619},{"i":"144258","t":"单选","q":"某钢铁厂因铁矿石价格上涨，增加了该厂的预付资本数量，这使得该厂的资本构成发生了变化，所变化的资本构成是()","o":{"A":"A.资本技术构成","B":"B.资本价值构成","C":"C.资本物质构成","D":"D.资本有机构成"},"a":"B","j":"<p>某钢铁厂因<span style=\"background-color: #f8cac6; color: #000000;\">铁矿石价格上涨</span>，增加了该厂的预付资本数量，这使得该厂的资本构成发生了变化，<strong>所变化的资本构成是</strong>()</p>\n<p>A.资本技术构成 <span style=\"background-color: #f8cac6; color: #000000;\">对应技术变化</span></p>\n<p>B.资本价值构成&radic;</p>\n<p>C.资本物质构成 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>D.资本有机构成 <span style=\"background-color: #f8cac6; color: #000000;\">资本有机构成是由资本的技术构成决定并反映技术构成变化的资本价值构成。实际也还是对应技术变化，因为技术构成变了，有机构成一定会变</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本价值构成对应价格涨跌。</span></p>","k":"考点72 资本积累★★","kid":"712","r":13416,"tot":25588},{"i":"144259","t":"单选","q":"第二次世界大战以后，资本主义国家经历了第三次科学技术革命，电子计算机、数控机床等自动化装置在生产中得到比较普遍的应用，机器大工业发展到自动化阶段。工业机器人的开发和利用，代替了工人大量的体力劳动和部分脑力劳动，直接从事生产操作的工人大大减少，甚至出现了少数所谓的“无人工厂”。“无人工厂”的出现说明()","o":{"A":"A.剩余价值来源的改变","B":"B.剩余价值生产所使用的生产工具更加先进了","C":"C.机器和工人共同创造了剩余价值","D":"D.成为资本主义社会失业现象产生的根源"},"a":"B","j":"<p>第二次世界大战以后，资本主义国家经历了第三次科学技术革命，电子计算机、数控机床等自动化装置在生产中得到比较普遍的应用，机器大工业发展到自动化阶段。工业机器人的开发和利用，代替了工人大量的体力劳动和部分脑力劳动，直接从事生产操作的工人大大减少，甚至出现了少数所谓的&ldquo;无人工厂&rdquo;。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">&ldquo;无人工厂&rdquo;的出现</span><strong>说明</strong>()</p>\n<p>A.剩余价值来源的<strong>改变 </strong><span style=\"background-color: #f8cac6; color: #000000;\">剩余价值的唯一源泉是剩余劳动</span></p>\n<p>B.剩余价值生产所使用的生产工具更加先进了&radic;</p>\n<p>C.机器和工人共同<strong>创造了</strong>剩余价值 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义生产自动化条件下，雇佣工人的剩余劳动仍然是这种剩余价值的唯一源泉，而不是共同创造</span></p>\n<p>D.成为资本主义社会失业现象产生的根源 <span style=\"background-color: #f8cac6; color: #000000;\">这是资本积累的后果</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">因为&ldquo;无人工厂&rdquo;本质上还是机器，只是把原有的价值转移到产品中去，而不创造新价值，更不能创造剩余价值。</span></p>","k":"考点67 生产自动化条件下剩余价值的源泉","kid":"189","r":19597,"tot":23984},{"i":"144260","t":"单选","q":"在资本主义社会里，资本家雇佣工人进行劳动并支付相应的工资。资本主义工资的本质是()","o":{"A":"A.工人所获得的资本家的预付资本","B":"B.工人劳动力的价值或价格","C":"C.工人所创造的剩余价值的一部分","D":"D.工人全部劳动的报酬"},"a":"B","j":"<p>在资本主义社会里，资本家雇佣工人进行劳动并支付相应的工资。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义工资</span>的<strong>本质是</strong>()</p>\n<p>A.工人所获得的资本家的<strong>预付资本 </strong><span style=\"background-color: #f8cac6; color: #000000;\">是资本家的投资，不是本质</span></p>\n<p>B.工人劳动力的价值或价格&radic;</p>\n<p>C.工人所创造的剩余价值的一部分<span style=\"background-color: #f8cac6; color: #000000;\"> 剩余价值不可能被工人拿走，是被资本家无偿占有</span></p>\n<p>D.工人全部劳动的报酬 <span style=\"background-color: #f8cac6; color: #000000;\">这是工资的表现，不是本质</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义工资的本质是工人劳动力的价值或价格。</span></p>","k":"考点68 资本主义工资★","kid":"192","r":16988,"tot":24380},{"i":"144261","t":"单选","q":"马克思通过对“劳动”和“劳动力”的区分，揭示了资本主义生产关系下的不合理分配制度。实际上，资本家花费了劳动力商品的价值，通过雇佣劳动实际上占有了全部劳动生产所得。资本主义工资表现为全部劳动报酬，这就模糊了()","o":{"A":"A.个别劳动时间和社会必要劳动时间的界限","B":"B.具体劳动和抽象劳动的界限","C":"C.私人劳动和社会劳动的界限","D":"D.必要劳动和剩余劳动的界限"},"a":"D","j":"<p>马克思通过对&ldquo;劳动&rdquo;和&ldquo;劳动力&rdquo;的区分，揭示了资本主义生产关系下的不合理分配制度。实际上，资本家花费了劳动力商品的价值，通过雇佣劳动实际上占有了全部劳动生产所得。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义工资表现为全部劳动报酬</span>，这就<strong>模糊了</strong>()</p>\n<p>A.个别劳动时间和社会必要劳动时间的界限</p>\n<p>B.具体劳动和抽象劳动的界限 <span style=\"background-color: #f8cac6; color: #000000;\">ABC这是劳动价值论内容，不合题意</span></p>\n<p>C.私人劳动和社会劳动的界限</p>\n<p>D.必要劳动和剩余劳动的界限&radic;</p>\n<p>【答案】D<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义工资表现为全部劳动报酬，这就模糊了必要劳动和剩余劳动的界限。口诀可以记忆为&ldquo;必胜&rdquo;。</span></p>","k":"考点68 资本主义工资★","kid":"192","r":18518,"tot":24263},{"i":"144262","t":"单选","q":"社会生产是连续不断进行的。这种连续不断重复的生产就是再生产，每次经济危机发生期间总有许多企业或因产品积压、或因订单缺乏等致使其无法继续进行再生产而被迫倒闭。那些因产品积压而倒闭的企业主要是由于无法实现其生产过程中的()","o":{"A":"A.实物替换","B":"B.价值补偿","C":"C.增殖补偿","D":"D.劳动补偿"},"a":"B","j":"<p>社会生产是连续不断进行的。这种连续不断重复的生产就是再生产，每次经济危机发生期间总有许多企业或因产品积压、或因订单缺乏等致使其无法继续进行再生产而被迫倒闭。<span style=\"color: #e03e2d;\">||</span>那些<span style=\"background-color: #f8cac6; color: #000000;\">因产品积压而倒闭的企业</span>主要是由于<strong>无法实现其生产过程中</strong>的()</p>\n<p>A.实物替换 <span style=\"background-color: #f8cac6; color: #000000;\">对应的是&ldquo;买得到&rdquo;,与题意无关</span></p>\n<p>B.价值补偿&radic;</p>\n<p>C.增殖补偿 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>D.劳动补偿 <span style=\"background-color: #f8cac6; color: #000000;\">无此表述</span></p>\n<p>【答案】B<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">价值补偿对应的是&ldquo;卖不出去&rdquo;,也就是材料所说的&ldquo;产品积压&rdquo;。</span></p>","k":"考点75 社会再生产","kid":"715","r":16171,"tot":24781},{"i":"144263","t":"多选","q":"马克思在《资本论》中指出：“在生产过程中，劳动者不仅把劳动力本身的价值转变为生产品的价值，而且……由于他的劳动的形式，他同时也把生产资料的价值转交给生产品，并因而把它保存在生产品中。”这段话揭示了()","o":{"A":"A.不变资本通过具体劳动转移价值，其价值量不发生改变","B":"B.可变资本通过抽象劳动再生产出自身价值并创造剩余价值","C":"C.资本的各个组成部分在价值增殖过程中的地位和作用是不同的","D":"D.劳动力本身价值的转移过程就是剩余价值的生产过程"},"a":"ABC","j":"<p>马克思在《资本论》中指出：&ldquo;在生产过程中，劳动者不仅把劳动力本身的价值转变为生产品的价值，而且&hellip;&hellip;由于他的劳动的形式，他同时也把生产资料的价值转交给生产品，并因而把它保存在生产品中。&rdquo;<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">这段话</span><strong>揭示了</strong>()</p>\n<p>A.不变资本通过具体劳动转移价值，其价值量不发生改变&radic;</p>\n<p>B.可变资本通过抽象劳动再生产出自身价值并创造剩余价值&radic;</p>\n<p>C.资本的各个组成部分在价值增殖过程中的地位和作用是不同的&radic;</p>\n<p>D.<strong>劳动力</strong>本身价值的<strong>转移过程</strong>就是剩余价值的生产过程 <span style=\"background-color: #f8cac6; color: #000000;\">劳动力价值不是被&ldquo;转移&rdquo;而是被&ldquo;再生产&rdquo;出来的</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">不变资本即以生产资料(物)形态存在的资本，可变资本是以劳动力(人)形态存在的资本。它们在价值增殖过程中的地位和作用是不同的。不变资本不发生增殖，仅仅发生物质形态的变化(比如面粉变面包),只有可变资本才发生价值增值。根据口诀&ldquo;人的价值要创造，物的价值要转移，抽象劳动对应人，具体劳动对应物&rdquo;,选项ABC正确。</span></p>","k":"考点65 资本的区分★★","kid":"185","r":10384,"tot":25631},{"i":"144264","t":"多选","q":"商品经济是以交换为目的而进行生产的经济形式，是一定社会历史条件的产物。商品经济得以产生的社会历史条件有()","o":{"A":"A.从小商品经济中分化出来","B":"B.存在社会分工","C":"C.从商人和高利贷者转化而来","D":"D.生产资料和劳动产品属于不同的所有者"},"a":"BD","j":"<p>商品经济是以交换为目的而进行生产的经济形式，是一定社会历史条件的产物。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">商品经济得以产生的社会历史条件</span><strong>有</strong>()</p>\n<p>A.从小商品经济中分化出来 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义萌芽的途径</span></p>\n<p>B.存在社会分工&radic;</p>\n<p>C.从商人和高利贷者转化而来 <span style=\"background-color: #f8cac6; color: #000000;\">资本主义萌芽的途径</span></p>\n<p>D.生产资料和劳动产品属于不同的所有者&radic;</p>\n<p>【答案】BD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">商品经济得以产生的社会历史条件有存在社会分工、生产资料和劳动产品属于不同的所有者。</span></p>","k":"考点54 商品经济的形成和发展","kid":"159","r":10084,"tot":25182},{"i":"144265","t":"多选","q":"人们往往将汉语中的“价”“值”二字与金银财宝等联系起来，而这两字的偏旁却都是“人”,示意价值在“人”。马克思劳动价值论透过商品交换的物与物的关系，揭示了商品价值的科学内涵，其主要观点有()","o":{"A":"A.劳动是社会财富的唯一源泉","B":"B.具体劳动是商品价值的实体","C":"C.价值是凝结在商品中的一般人类劳动","D":"D.价值在本质上体现了生产者之间的社会关系"},"a":"CD","j":"<p>人们往往将汉语中的&ldquo;价&rdquo;&ldquo;值&rdquo;二字与金银财宝等联系起来，而这两字的偏旁却都是&ldquo;人&rdquo;,示意价值在&ldquo;人&rdquo;。<span style=\"color: #e03e2d;\">|</span>马克思劳动价值论透过商品交换的物与物的关系，揭示了<span style=\"background-color: #f8cac6; color: #000000;\">商品价值的科学内涵</span>，其<strong>主要观点有</strong>()</p>\n<p>A.劳动是社会财富的<strong>唯一源泉</strong> <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述K错误</span></p>\n<p>B.具体劳动是商品<strong>价值的实体</strong> <span style=\"background-color: #f8cac6; color: #000000;\">是抽象劳动，即凝结在商品中的无差别的一般人类劳动</span></p>\n<p>C.价值是凝结在商品中的<strong>一般人类劳动</strong>&radic;</p>\n<p>D.价值在本质上体现了生产者之间的<strong>社会</strong>关系&radic;</p>\n<p>【答案】CD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">价值是凝结在商品中的一般人类劳动。价值在本质上体现了生产者之间的社会关系。</span></p>","k":"考点55 商品的二因素★★★","kid":"162","r":9176,"tot":25554},{"i":"144266","t":"多选","q":"马克思指出，“一切劳动，一方面是人类劳动力在生理学意义上的耗费；就相同的或抽象的人类劳动这个属性来说，它形成商品价值。一切劳动，另一方面是人类劳动力在特殊的有一定目的的形式上的耗费；就具体的有用的劳动这个属性来说，它生产使用价值”。这一表述深刻地揭示了劳动二重性的内涵。其主要观点具体表现在()","o":{"A":"A.具体劳动是劳动的自然属性，创造商品的使用价值","B":"B.抽象劳动是劳动的社会属性，形成商品的价值","C":"C.具体劳动和抽象劳动在时间上和空间上是统一的","D":"D.具体劳动和抽象劳动是各自独立存在的两种劳动或两次劳动"},"a":"ABC","j":"<p>马克思指出，&ldquo;一切劳动，一方面是人类劳动力在生理学意义上的耗费；就相同的或抽象的人类劳动这个属性来说，它形成商品价值。一切劳动，另一方面是人类劳动力在特殊的有一定目的的形式上的耗费；就具体的有用的劳动这个属性来说，它生产使用价值&rdquo;。<span style=\"color: #e03e2d;\">||</span>这一表述深刻地揭示了<span style=\"background-color: #f8cac6; color: #000000;\">劳动二重性的内涵</span>。<strong>其主要观点具体表现在</strong>()</p>\n<p>A.具体劳动是劳动的自然属性，创造商品的使用价值&radic;</p>\n<p>B.抽象劳动是劳动的社会属性，形成商品的价值&radic;</p>\n<p>C.具体劳动和抽象劳动在时间上和空间上是统一的&radic;</p>\n<p>D.具体劳动和抽象劳动是各自独立存在的<strong>两种劳动或两次劳动<span style=\"color: #000000;\"> </span></strong><span style=\"background-color: #f8cac6; color: #000000;\">是同一劳动的两重属性</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">具体劳动是劳动的自然属性，创造商品的使用价值。对应K:具体劳动&mdash;使用价值一自然属性一具体形式、有差别、特殊。抽象劳动是劳动的社会属性，形成商品的价值。对应K:抽象劳动价值&mdash;社会属性一抽象、无差别、一般。任何一种生产商品的劳动，一方面是特殊的具体劳动，另一方面又是一般的抽象劳动。</span></p>","k":"考点56 生产商品的劳动二重性★★","kid":"164","r":17371,"tot":23154},{"i":"144267","t":"多选","q":"数字人民币是由中国人民银行发行的数字形式的法定货币，具有双离线支付功能，相较于纸币，其安全性更高，数字人民币和纸币一样，是一种货币符号。货币的产生()","o":{"A":"A.使整个商品世界分化为具体商品和货币两极","B":"B.使商品的使用价值能够寓于价值之中","C":"C.促进了商品经济的发展，有利于解决商品交换的困难","D":"D.使商品内在的使用价值和价值的矛盾发展成为外在的商品和货币的矛盾"},"a":"ACD","j":"<p>数字人民币是由中国人民银行发行的数字形式的法定货币，具有双离线支付功能，相较于纸币，其安全性更高，数字人民币和纸币一样，是一种货币符号。<span style=\"color: #e03e2d;\">|</span><strong>货币的产生</strong>()</p>\n<p>A.使整个商品世界分化为具体商品和货币两极&radic;</p>\n<p>B.使商品的使用价值能够<strong>寓于</strong>价值之中 <span style=\"background-color: #f8cac6; color: #000000;\">顺序说反了，价值寓于使用价值</span></p>\n<p>C.促进了商品经济的发展，有利于解决商品交换的困难&radic;</p>\n<p>D.使商品内在的使用价值和价值的矛盾发展成为外在的商品和货币的矛盾&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">货币的产生使整个商品世界分化为具体商品和货币两极，一极：只代表使用价值的具体商品；一极：只代表价值的货币。货币的产生促进了商品经济的发展，有利于解决商品交换的困难，使商品内在的使用价值和价值的矛盾发展成为外在的商品和货币的矛盾。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":11423,"tot":24441},{"i":"144268","t":"多选","q":"马克思曾这样说道，“商品爱货币，但是真爱情的道路绝不是平坦的”。这是因为货币的诞生虽然有利于解决商品交换的困难，促进了商品经济的发展，但是货币的出现()","o":{"A":"A.决定着商品生产者的命运","B":"B.扩大和加深了商品经济的基本矛盾","C":"C.并未从根本上消除商品经济的基本矛盾","D":"D.自发地刺激社会生产力的发展"},"a":"BC","j":"<p>马克思曾这样说道，&ldquo;商品爱货币，但是真爱情的道路绝不是平坦的&rdquo;。这是因为货币的诞生虽然有利于解决商品交换的困难，促进了商品经济的发展，<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">但是货币</span>的<strong>出现</strong>()</p>\n<p>A.<strong>决定着</strong>商品生产者的命运 <span style=\"background-color: #f8cac6; color: #000000;\">私人劳动和社会劳动的矛盾决定着商品生产者的命运</span></p>\n<p>B.扩大和加深了商品经济的基本矛盾&radic;</p>\n<p>C.并未从根本上消除商品经济的基本矛盾&radic;</p>\n<p>D.<strong>自发地刺激社会生产力</strong>的发展 <span style=\"background-color: #f8cac6; color: #000000;\">这是价值规律的作用</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">货币的出现扩大和加深了商品经济的基本矛盾，并未从根本上消除商品经济的基本矛盾。</span></p>","k":"考点58 价值形式的发展与货币的产生★★","kid":"170","r":11387,"tot":24880},{"i":"144269","t":"多选","q":"马克思指出，所谓资本原始积累“只不过是生产者和生产资料分离的历史过程。这个过程所以表现为‘原始的’,因为它形成资本及与之相适应的生产方式的前史”。资本原始积累的主要途径有()","o":{"A":"A.用暴力手段剥夺农民土地","B":"B.用野蛮手段进行殖民掠夺","C":"C.用剥削手段榨取剩余价值","D":"D.用资本手段获取市场暴利"},"a":"AB","j":"<p>马克思指出，所谓资本原始积累&ldquo;只不过是生产者和生产资料分离的历史过程。这个过程所以表现为&lsquo;原始的&rsquo;,因为它形成资本及与之相适应的生产方式的前史&rdquo;。<span style=\"background-color: #f8cac6; color: #000000;\">资本原始积累</span>的<strong>主要途径</strong>有()</p>\n<p>A.用暴力手段剥夺农民土地&radic;</p>\n<p>B.用野蛮手段进行殖民掠夺&radic;</p>\n<p>C.用剥削手段榨取剩余价值 <span style=\"background-color: #f8cac6; color: #000000;\">CD为资本主义生产方式确立后的积累方法</span></p>\n<p>D.用资本手段获取市场暴利</p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本原始积累的主要途径有用暴力手段剥夺农民土地，用野蛮手段进行殖民掠夺。</span></p>","k":"考点72 资本积累★★","kid":"712","r":13384,"tot":23483},{"i":"144270","t":"多选","q":"马克思指出：“资本主义社会的经济结构是从封建社会的经济结构中产生的。后者的解体使前者的要素得到解放。”资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市。资本主义产生的途径有()","o":{"A":"A.从小商品经济中分化出来","B":"B.用暴力手段剥夺农民的土地","C":"C.用暴力手段掠夺货币财富","D":"D.从商人和高利贷者转化而来"},"a":"AD","j":"<p>马克思指出：&ldquo;资本主义社会的经济结构是从封建社会的经济结构中产生的。后者的解体使前者的要素得到解放。&rdquo;资本主义萌芽于14世纪末15世纪初地中海沿岸的一些城市。<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义产生</span>的<strong>途径有</strong>()</p>\n<p>A.从小商品经济中分化出来&radic;</p>\n<p>B.用暴力手段剥夺农民的土地</p>\n<p>C.用暴力手段掠夺货币财富 <span style=\"background-color: #f8cac6; color: #000000;\">BC是资本原始积累的主要途径</span></p>\n<p>D.从商人和高利贷者转化而来&radic;</p>\n<p>【答案】AD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义萌芽的途径有从小商品经济中分化出来、从商人和高利贷者转化而来。</span></p>","k":"考点62 资本主义经济制度的产生","kid":"181","r":16695,"tot":22924},{"i":"144271","t":"多选","q":"劳动力成为商品是货币转化为资本的前提。劳动力并非天然就是商品，它只有在一定的历史条件下才会成为商品。劳动力成为商品必须具备的条件是()","o":{"A":"A.资本原始积累","B":"B.劳动者享有充分的人权","C":"C.劳动者除了自己的劳动力以外，自由得一无所有","D":"D.劳动力所有者是“自由人”,能自由支配自己的劳动力"},"a":"CD","j":"<p>劳动力成为商品是货币转化为资本的前提。劳动力并非天然就是商品，它只有在一定的历史条件下才会成为商品。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">劳动力成为商品</span>必须<strong>具备的条件是</strong>()</p>\n<p>A.资本原始积累 <span style=\"background-color: #f8cac6; color: #000000;\">劳动力成为商品的两个条件是在资本原始积累过程中逐渐形成的，与题意无关</span></p>\n<p>B.劳动者享有充分的人权 <span style=\"background-color: #f8cac6; color: #000000;\">与题意无关</span></p>\n<p>C.劳动者除了自己的劳动力以外，自由得一无所有&radic;</p>\n<p>D.劳动力所有者是&ldquo;自由人&rdquo;,能自由支配自己的劳动力&radic;</p>\n<p>【答案】CD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">劳动力成为商品必须具备的条件是劳动者除了自己的劳动力以外，自由得一无所有，只能出卖自己；劳动力所有者是&ldquo;自由人&rdquo;,能自由支配自己的劳动力。</span></p>","k":"考点63 劳动力成为商品与货币转化为资本★★★★","kid":"182","r":12734,"tot":23997},{"i":"144272","t":"多选","q":"在英国，从14世纪末到18世纪中叶这段时期，政府就曾经颁布各种劳工法令，强迫工人延长工作日。马克思对资本主义发展过程中由于过度延长劳动时间给工人阶级带来的损害作出这样的抨击：“资本主义生产——实质上就是剩余价值的生产，就是剩余劳动的吮吸——通过延长工作日，不仅使人的劳动力由于被夺去了道德上和身体上正常的发展和活动的条件而处于萎缩状态，而且使劳动力本身未老先衰和过早死亡。它靠缩短工人的寿命，在一定期限内延长工人的生产时间。”这种剩余价值的生产()","o":{"A":"A.是资本家通过延长工作日的长度或提高劳动强度而实现的","B":"B.缩短了必要劳动时间，相对延长了剩余劳动时间","C":"C.是通过社会各个生产部门的劳动生产率普遍提高实现的","D":"D.可以使资本家从工人身上榨取更多的剩余价值"},"a":"AD","j":"<p>在英国，从14世纪末到18世纪中叶这段时期，政府就曾经颁布各种劳工法令，强迫工人延长工作日。马克思对资本主义发展过程中由于过度延长劳动时间给工人阶级带来的损害作出这样的抨击：&ldquo;资本主义生产&mdash;&mdash;实质上就是剩余价值的生产，就是剩余劳动的吮吸&mdash;&mdash;<span style=\"background-color: #f8cac6; color: #000000;\">通过延长工作日</span>，不仅使人的劳动力由于被夺去了道德上和身体上正常的发展和活动的条件而处于萎缩状态，而且使劳动力本身未老先衰和过早死亡。它靠缩短工人的寿命，<span style=\"background-color: #f8cac6; color: #000000;\">在一定期限内延长工人的生产时间</span>。&rdquo;<span style=\"color: #e03e2d;\">Ⅱ</span>这种<strong>剩余价值的生产</strong>()</p>\n<p>A.是资本家通过延长工作日的长度或提高劳动强度而实现的&radic;</p>\n<p>B.<strong>缩短了</strong>必要劳动时间，<strong>相对延长了</strong>剩余劳动时间 <span style=\"background-color: #f8cac6; color: #000000;\">这是相对剩余价值生产的方式，不合题意</span></p>\n<p>C.是通过<strong>社会</strong>各个生产部门的劳动<strong>生产率普遍提高</strong>实现的 <span style=\"background-color: #f8cac6; color: #000000;\">这是相对剩余价值生产的方式，不合题意</span></p>\n<p>D.可以使资本家从工人身上榨取更多的剩余价值&radic;</p>\n<p>【答案】AD<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">剩余价值的生产是资本家通过延长工作日的长度或提高劳动强度而实现的，即绝对剩余价值的生产，符合题意&ldquo;通过延长工作日&rdquo;,在一定期限内延长工人的生产时间。剩余价值的生产可以使资本家从工人身上榨取更多的剩余价值，属于剩余价值生产的基本方法。</span></p>","k":"考点66 剩余价值生产的两种基本方法★","kid":"186","r":14673,"tot":23509},{"i":"144273","t":"多选","q":"马克思、恩格斯在《共产党宣言》中指出：“资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口——过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢?”资本主义社会生产力迅速发展的主要原因是()","o":{"A":"A.资本追逐剩余价值的内在动力","B":"B.市场激烈竞争的外在压力","C":"C.无产阶级对资产阶级的斗争","D":"D.资本主义国家对市场的全面控制"},"a":"AB","j":"<p>马克思、恩格斯在《共产党宣言》中指出：&ldquo;资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。自然力的征服，机器的采用，化学在工业和农业中的应用，轮船的行驶，铁路的通行，电报的使用，整个大陆的开垦，河川的通航，仿佛用法术从地下呼唤出来的大量人口&mdash;&mdash;过去哪一个世纪料想到在社会劳动里蕴藏有这样的生产力呢?&rdquo;<span style=\"color: #e03e2d;\">||</span><span style=\"background-color: #f8cac6; color: #000000;\">资本主义社会生产力迅速发展的主要原因</span><strong>是</strong>()</p>\n<p>A.资本追逐剩余价值的内在动力&radic;</p>\n<p>B.市场激烈竞争的外在压力&radic;</p>\n<p>C.无产阶级对资产阶级的斗争 <span style=\"background-color: #f8cac6; color: #000000;\">一直有斗争，不是资本主义生产力迅速发展的原因</span></p>\n<p>D.资本主义国家对市场的全面控制 <span style=\"background-color: #f8cac6;\"><span style=\"color: #000000;\">属于国家垄断资本主义在二战后的变化，后续又放松了控制。与题意无关</span></span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义社会生产力迅速发展的主要原因是资本追逐剩余价值的内在动力，市场激烈竞争的外在压力。</span></p>","k":"","kid":"","r":13575,"tot":23642},{"i":"144274","t":"多选","q":"为了追逐最大化的利润，资本家总是想方设法地进行资本积累，而资本积累的源泉是剩余价值。一般而言，资本积累规模的大小取决于()","o":{"A":"A.所用资本与所费资本之间的差额","B":"B.劳动生产率的高低","C":"C.资本家垫付资本的大小","D":"D.资本家对工人的剥削程度"},"a":"ABCD","j":"<p>为了追逐最大化的利润，资本家总是想方设法地进行资本积累，而资本积累的源泉是剩余价值。一般而言，<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">资本积累规模的大小</span><strong>取决于</strong>()</p>\n<p>A.所用资本与所费资本之间的差额&radic;</p>\n<p>B.劳动生产率的高低&radic;</p>\n<p>C.资本家垫付资本的大小&radic;</p>\n<p>D.资本家对工人的剥削程度&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本积累规模的大小取决于所用资本与所费资本之间的差额，劳动生产率的高低，资本家垫付资本的大小，资本家对工人的剥削程度。</span></p>","k":"考点72 资本积累★★","kid":"712","r":9527,"tot":24594},{"i":"144275","t":"多选","q":"资本所有者把从劳动者那里赚来的剩余价值的一部分用于个人消费，另一部分转化为资本，用于购买扩大生产规模所需追加的资本要素和劳动要素。资本积累是生产发展的必然趋势，其导致的社会现象包括()","o":{"A":"A.资本家和封建贵族用暴力剥夺农民土地","B":"B.社会的两极分化加剧","C":"C.失业现象产生","D":"D.资本从利润率高的部门转向利润率低的部门"},"a":"BC","j":"<p>资本所有者把从劳动者那里赚来的剩余价值的一部分用于个人消费，另一部分转化为资本，用于购买扩大生产规模所需追加的资本要素和劳动要素。<span style=\"background-color: #f8cac6; color: #000000;\">资本积累</span>是生产发展的必然趋势，其<span style=\"background-color: #f8cac6; color: #000000;\">导致的社会现象</span><strong>包括</strong>()</p>\n<p>A.资本家和封建贵族用暴力剥夺农民土地 <span style=\"background-color: #f8cac6; color: #000000;\">资本原始积累的途径</span></p>\n<p>B.社会的两极分化加剧&radic;</p>\n<p>C.失业现象产生&radic;</p>\n<p>D.资本从<strong>利润率高的部门转向利润率低</strong>的部门 <span style=\"background-color: #f8cac6; color: #000000;\">资本从利润率低的部门转向利润率高的部门，从而导致利润率平均化</span></p>\n<p>【答案】BC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本积累不但是社会财富占有两极分化的重要原因，而且是资本主义社会失业现象产生的根源。</span></p>","k":"考点72 资本积累★★","kid":"712","r":13185,"tot":23572},{"i":"144276","t":"多选","q":"当今世界正处在新科技革命和产业革命的交汇点，以机器人技术为代表的科技产业发展十分迅速。机器人在生产过程中的广泛使用，使资本有机构成不断提高。然而，就一般意义而言，资本有机构成的提高实际上是()","o":{"A":"A.由资本的本性决定的","B":"B.不以人的意志为转移的一般趋势","C":"C.社会产生相对过剩人口的一个重要原因","D":"D.一个社会增长财富和消除贫困的根本途径"},"a":"ABC","j":"<p>当今世界正处在新科技革命和产业革命的交汇点，以机器人技术为代表的科技产业发展十分迅速。机器人在生产过程中的广泛使用，使资本有机构成不断提高。然而，就一般意义而言，<span style=\"background-color: #f8cac6; color: #000000;\">资本有机构成的提高</span><strong>实际上是</strong>()</p>\n<p>A.由资本的本性决定的&radic;</p>\n<p>B.不以人的意志为转移的一般趋势&radic;</p>\n<p>C.社会产生相对过剩人口的一个重要原因&radic;</p>\n<p>D.一个社会增长财富和消除贫困的<strong>根本途径 </strong><span style=\"background-color: #f8cac6; color: #000000;\">第一梯队K错误</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本的本性就是不断获取剩余价值，这会使得资本家不断改进技术，使资本有机构成提高。在资本主义生产过程中，资本有机构成的提高是一般趋势，也就是规律。资本有机构成提高，可变资本相对量不断减少，出现了相对过剩人口。</span></p>","k":"考点72 资本积累★★","kid":"712","r":13145,"tot":23469},{"i":"144277","t":"多选","q":"马克思指出：“资本主义积累不断地并且同它的能力和规模成比例地生产出相对的，即超过资本增殖的平均需要的，因而是过剩的或追加的工人人口。”“过剩的工人人口是积累或资本主义基础上的财富发展的必然产物，但是这种过剩人口反过来又成为资本主义积累的杠杆，甚至成为资本主义生产方式存在的一个条件。”上述论断表明()","o":{"A":"A.资本主义生产周期性特征需要有相对过剩的人口规律与之相适应","B":"B.资本主义社会过剩人口之所以是相对的，是因为它不为资本价值增殖所需要","C":"C.资本主义积累必然导致工人人口的供给相对于资本的需要而过剩","D":"D.资本主义积累使得资本主义社会的人口失业规模呈现越来越大的趋势"},"a":"ABC","j":"<p>马克思指出：&ldquo;<span style=\"background-color: #f8cac6; color: #000000;\">资本主义积累</span>不断地并且同它的能力和规模成比例地生产出相对的，即<span style=\"background-color: #f8cac6; color: #000000;\">超过资本增殖的平均需要</span>的，因而是<span style=\"background-color: #f8cac6; color: #000000;\">过剩的</span>或追加的<span style=\"background-color: #f8cac6; color: #000000;\">工人人口</span>。&rdquo;&ldquo;过剩的工人人口是积累或资本主义基础上的财富发展的<span style=\"background-color: #f8cac6; color: #000000;\">必然产物</span>，但是这种过剩人口反过来又成为资本主义积累的杠杆，甚至<span style=\"background-color: #f8cac6; color: #000000;\">成为资本主义生产方式存在的一个条件</span>。&rdquo;<span style=\"color: #e03e2d;\">|</span>上述论断<strong>表明</strong>()</p>\n<p>A.资本主义生产周期性特征需要有相对过剩的人口规律与之相适应&radic;</p>\n<p>B.资本主义社会过剩人口之所以是相对的，是因为它不为资本价值增殖所需要&radic;</p>\n<p>C.资本主义积累必然导致工人人口的供给相对于资本的需要而过剩&radic;</p>\n<p>D.资本主义积累使得资本主义社会的人口<strong>失业规模呈现越来越大</strong>的趋势 <span style=\"background-color: #f8cac6; color: #000000;\">政治会通过各种干预措施缓解失业，失业规模不是呈现越来越大趋势</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6;\">材<span style=\"color: #000000;\">料思考题</span></span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义生产周期性特征需要有相对过剩的人口规律与之相适应，即材料中&ldquo;必然产物&rdquo;&ldquo;成为资本主义生产方式存在的一个条件&rdquo;。资本主义生产和积累不可避免地推动资本有机构成提高，带来相对过剩人口的出现。资本主义社会过剩人口之所以是相对的，是因为它不为资本价值增殖所需要，基础知识对，且符合材料&ldquo;超过资本增值需要&rdquo;。资本主义积累必然导致工人人口的供给相对于资本的需要而过剩，基础知识对，且符合材料&ldquo;过剩人口&rdquo;。</span></p>","k":"考点72 资本积累★★","kid":"712","r":5658,"tot":25303},{"i":"144278","t":"多选","q":"资本循环是资本实现价值增殖的重要前提。所谓资本循环，是指资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。产业资本循环过程中在空间上同时存在的资本形式有()","o":{"A":"A.货币资本","B":"B.借贷资本","C":"C.生产资本","D":"D.商品资本"},"a":"ACD","j":"<p>资本循环是资本实现价值增殖的重要前提。所谓资本循环，是指资本从一种形式出发，经过一系列形式的变化，又回到原来出发点的运动。<span style=\"color: #e03e2d;\">Ⅱ</span><span style=\"background-color: #f8cac6; color: #000000;\">产业资本循环过程中在空间上同时存在</span>的<strong>资本形式有</strong>()</p>\n<p>A.货币资本&radic;</p>\n<p>B.借贷资本 <strong>不合题意</strong></p>\n<p>C.生产资本&radic;</p>\n<p>D.商品资本&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">产业资本循环过程中在空间上同时存在的资本形式有货币资本(对应购买阶段)、生产资本(对应生产阶段)、商品资本(对应售卖阶段)。</span></p>","k":"考点73 资本循环","kid":"713","r":15271,"tot":22850},{"i":"144279","t":"多选","q":"资本主义的生产目的是追逐利润最大化。为了获得尽可能多的利润，分布在不同部门(行业)的资本家之间必然展开激烈的竞争，而竞争的结果必将导致利润率的平均化。利润率平均化的过程意味着()","o":{"A":"A.各部门资本家在加强对工人阶级的剥削上有着共同的阶级利益","B":"B.各部门内不同资本家的等量投资所得到的利润大体上均等","C":"C.某企业工人创造的剩余价值有被其他资本家侵占的可能","D":"D.不从事直接生产的银行资本家所获得的利润总是低于平均利润"},"a":"AC","j":"<p>资本主义的生产目的是追逐利润最大化。为了获得尽可能多的利润，分布在不同部门(行业)的资本家之间必然展开激烈的竞争，而竞争的结果必将导致利润率的平均化。<span style=\"background-color: #f8cac6; color: #000000;\">利润率平均化的过程</span><strong>意味着</strong>()</p>\n<p>A.<strong>各部门</strong>资本家在加强对工人阶级的剥削上有着共同的阶级利益&radic;</p>\n<p>B.<strong>各部门内</strong>不同资本家的等量投资所得到的利润大体上均等 <span style=\"background-color: #f8cac6; color: #000000;\">是不同部门之间的资本家，而不是部门内</span></p>\n<p>C.某企业工人创造的剩余价值有被其他资本家侵占的可能&radic;<span style=\"background-color: #f8cac6; color: #000000;\">如银行资本家有可能得到</span></p>\n<p>D.不从事直接生产的银行资本家所获得的利润<strong>总是低于</strong>平均利润 <span style=\"background-color: #f8cac6; color: #000000;\">绝对表述K错误</span></p>\n<p>【答案】AC<span style=\"background-color: #f8cac6;\">判<span style=\"color: #000000;\">断纯背题</span></span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本家之间存在竞争和矛盾，但资本家之间有着共同的阶级利益，就是加强对工人阶级的剥削。某企业工人创造的剩余价值有被其他资本家侵占的可能，如银行资本家有可能得到。</span></p>","k":"考点70 平均利润的形成和剩余价值的分配","kid":"197","r":8137,"tot":24669},{"i":"144280","t":"多选","q":"资本主义生产的目的是获得利润。为了得到尽可能高的利润率和尽可能多的利润，不同生产部门的资本家之间必然展开激烈的竞争，大量资本必然从利润率低的部门转投到利润率高的部门，从而导致利润率平均化。利润转化为平均利润()","o":{"A":"A.不同部门的资本家集团要求按照等量资本获得等量利润的原则来瓜分剩余价值","B":"B.是剩余价值规律和竞争规律作用的必然结果","C":"C.商品价值就转化为生产价格","D":"D.价值规律的实现形式发生了变化"},"a":"ABCD","j":"<p>资本主义生产的目的是获得利润。为了得到尽可能高的利润率和尽可能多的利润，不同生产部门的资本家之间必然展开激烈的竞争，大量资本必然从利润率低的部门转投到利润率高的部门，从而导致利润率平均化。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">利润转化为平均利润</span>()</p>\n<p>A.<strong>不同部门的资本家</strong>集团要求按照<strong>等量资本获得等量利润的</strong>原则来瓜分剩余价值&radic;</p>\n<p>B.是<strong>剩余价值规律和竞争规律</strong>作用的必然结果&radic;</p>\n<p>C.商品价值就转化为生产价格&radic;</p>\n<p>D.价值规律的实现形式发生了变化&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">不同部门的资本家集团要求按照等量资本获得等量利润的原则来瓜分剩余价值。利润转化为平均利润是剩余价值规律和竞争规律作用的必然结果。利润转化为平均利润商品价值就转化为生产价格，所以商品不再以价值而是以生产价格为基础进行交换，市场价格的变动不再以价值为中心，而是以生产价格为中心。利润转化为平均利润价值规律的实现形式发生了变化，所以生产价格是价值的转化形式，商品按照生产价格而不是价值出售。</span></p>","k":"考点70 平均利润的形成和剩余价值的分配","kid":"197","r":6009,"tot":25541},{"i":"144281","t":"多选","q":"2008年由美国次贷危机引发了全球性的经济危机，很多西方人感叹这一次经济危机从根本上仍未超出一百多年前马克思在《资本论》中对资本主义经济危机的理论判断和精辟分析。马克思对资本主义经济危机科学分析的深刻性主要表现为()","o":{"A":"A.指明经济危机的实质是生产相对过剩","B":"B.揭示造成相对过剩的制度原因是生产资料的资本主义私有制","C":"C.指出经济危机的深层根源是人性的贪婪","D":"D.强调政府对经济的干预是摆脱经济危机的根本出路"},"a":"AB","j":"<p>2008年由美国次贷危机引发了全球性的经济危机，很多西方人感叹这一次经济危机从根本上仍未超出一百多年前马克思在《资本论》中对资本主义经济危机的理论判断和精辟分析。<span style=\"color: #e03e2d;\">|</span><span style=\"background-color: #f8cac6; color: #000000;\">马克思对资本主义经济危机科学分析的深刻性</span><strong>主要表现为</strong>()</p>\n<p>A.指明经济危机的<strong>实质</strong>是生产相对过剩&radic;</p>\n<p>B.揭示造成相对过剩的<strong>制度原因</strong>是生产资料的资本主义私有制&radic;</p>\n<p>C.指出经济危机的<strong>深层根源</strong>是人性的贪婪 <span style=\"background-color: #f8cac6; color: #000000;\">明显常识错误</span></p>\n<p>D.强调政府对经济的干预是摆脱经济危机的<strong>根本出路 </strong><span style=\"background-color: #f8cac6; color: #000000;\">第一梯队K对应错误</span></p>\n<p>【答案】AB<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">马克思对资本主义经济危机科学分析的深刻性主要表现为指明经济危机的实质是生产相对过剩，揭示造成相对过剩的制度原因是生产资料的资本主义私有制。</span></p>","k":"考点76 资本主义的基本矛盾与经济危机★★","kid":"716","r":11682,"tot":23664},{"i":"144282","t":"多选","q":"马克思说：“一切现实的危机的最终原因始终是：群众贫穷和群众的消费受到限制，而与此相对立，资本主义生产却竭力发展生产力，好像只有社会的绝对的消费能力才是生产力发展的界限。”这段论述表明()","o":{"A":"A.经济危机的发生与群众的贫穷及其消费能力受到限制有关","B":"B.经济危机的发生根本上在于资本主义的基本矛盾","C":"C.资本积累与无限扩大生产也是经济危机发生的原因","D":"D.社会的绝对的消费能力导致了经济危机的发生"},"a":"ABC","j":"<p>马克思说：&ldquo;一切现实的危机的最终原因始终是：<span style=\"background-color: #f8cac6; color: #000000;\">群众贫穷</span>和群众的<span style=\"background-color: #f8cac6; color: #000000;\">消费受到限</span>制，而与此相对立，<span style=\"background-color: #f8cac6; color: #000000;\">资本主义生产却竭力发展生产力</span>，好像只有社会的绝对的消费能力才是生产力发展的界限。&rdquo;这段<strong>论述表明</strong>()</p>\n<p>A.经济危机的发生与群众的贫穷及其消费能力受到限制有关&radic;</p>\n<p>B.经济危机的发生<strong>根本上在于</strong>资本主义的基本矛盾&radic;</p>\n<p>C.<strong>资本积累与无限扩大生产</strong>也是经济危机发生的原因&radic;</p>\n<p>D.社会的<strong>绝对的消费能力导致了</strong>经济危机的发生 <span style=\"background-color: #f8cac6; color: #000000;\">基础知识K错误，不是社会绝对的消费能力</span></p>\n<p>【答案】ABC<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">经济危机的发生与群众的贫穷及其消费能力受到限制有关。经济危机的发生根本上在于资本主义的基本矛盾。资本积累与无限扩大生产也是经济危机发生的原因，符合材料&ldquo;资本主义生产竭力发展&hellip;&hellip;界限&rdquo;。</span></p>","k":"考点76 资本主义的基本矛盾与经济危机★★","kid":"716","r":14669,"tot":22796},{"i":"144283","t":"多选","q":"有一则寓言讲到：狐狸把鱼汤盛在平底的盘子里，请仙鹤来和它一起“平等”的喝鱼汤，结果仙鹤一点也没喝到，全被狐狸喝去了。这个寓言给人们的启示是，尽管资产阶级宣布“法律面前人人平等”,但是()","o":{"A":"A.法律名义上的平等掩盖着事实上的不平等","B":"B.这种形式上的平等即是资本主义的本质","C":"C.它的实质是将劳资之间经济利益的不平等合法化","D":"D.这种平等的权利是建立在财产不平等基础之上的权利"},"a":"ACD","j":"<p>有一则寓言讲到：狐狸把鱼汤盛在平底的盘子里，请仙鹤来和它一起&ldquo;平等&rdquo;的喝鱼汤，结果仙鹤一点也没喝到，全被狐狸喝去了。<span style=\"color: #e03e2d;\">Ⅱ</span>这个寓言给人们的<strong>启示</strong>是，<span style=\"color: #000000;\"><span style=\"background-color: #f8cac6;\">尽管资产阶级宣布&ldquo;法律面前人人平等&rdquo;</span>,</span>但是()</p>\n<p>A.法律名义上的平等掩盖着事实上的不平等&radic;</p>\n<p>B.这种形式上的平等<strong>即是</strong>资本主义的本质 <span style=\"background-color: #f8cac6; color: #000000;\">形式平等不等于真的平等。资本主义的本质是剥削关系</span></p>\n<p>C.它的实质是将劳资之间经济利益的不平等合法化&radic;</p>\n<p>D.这种平等的权利是建立在财产不平等基础之上的权利&radic;</p>\n<p>【答案】ACD<span style=\"background-color: #f8cac6; color: #000000;\">材料思考题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">法律名义上的平等掩盖着事实上的不平等，所以狐狸喝到，仙鹤没喝到。它的实质是将劳资之间经济利益的不平等合法。这种平等的权利是建立在财产不平等基础之上的权利。</span></p>","k":"考点77 资本主义上层建筑★","kid":"717","r":10759,"tot":23685},{"i":"144284","t":"多选","q":"资本主义政治制度的形成和发展在人类社会历史的发展进程中曾经起过重要的进步作用。但是，由于资本主义政治制度本质上是资产阶级实行政治统治和社会管理的手段和方式，是为资产阶级专政服务的，因此它不可避免地有其阶级的和历史的局限性。其局限性表现在()","o":{"A":"A.资本主义国家的政党制是一种维护资产阶级统治的政治制度","B":"B.法律名义上的平等掩盖着事实上的不平等","C":"C.资本主义的民主是金钱操纵下的民主","D":"D.政党恶斗相互掣肘，决策效率低下，激化社会矛盾"},"a":"ABCD","j":"<p><span style=\"background-color: #f8cac6; color: #000000;\">资本主义政治制度</span>的形成和发展在人类社会历史的发展进程中曾经起过重要的进步作用。但是，由于资本主义政治制度本质上是资产阶级实行政治统治和社会管理的手段和方式，是为资产阶级专政服务的，因此它不可避免地有其阶级的和历史的局限性。<span style=\"color: #e03e2d;\">Ⅱ</span>其<span style=\"background-color: #f8cac6; color: #000000;\">局限性</span><strong>表现在</strong>()</p>\n<p>A.资本主义国家的政党制是一种维护资产阶级统治的政治制度&radic;</p>\n<p>B.法律名义上的平等掩盖着事实上的不平等&radic;</p>\n<p>C.资本主义的民主是金钱操纵下的民主&radic;</p>\n<p>D.政党恶斗相互掣肘，决策效率低下，激化社会矛盾&radic;</p>\n<p>【答案】ABCD<span style=\"background-color: #f8cac6; color: #000000;\">判断纯背题</span></p>\n<p>【解析】<span style=\"color: #e03e2d;\">资本主义政治制度的局限性表现在资本主义国家的政党制是一种维护资产阶级统治的政治制度，法律名义上的平等掩盖着事实上的不平等，资本主义的民主是金钱操纵下的民主，政党恶斗相互掣肘，决策效率低下，激化社会矛盾。</span></p>","k":"考点77 资本主义上层建筑★","kid":"717","r":17641,"tot":22169}]};
